(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["audio"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-codec-lm-stream"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-1\">一 · 一次首包抖动事故：预填把解码饿死</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-2\">二 · 它到底解决哪一个推理问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-3\">三 · 机制的数据流：谁先谁后、谁释放谁</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-4\">四 · 它明确不解决什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-5\">五 · 与相邻算法的分界与选型判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-6\">六 · 预填洪峰下的首包抖动：这套方案管什么、不管什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-7\">七 · 条件 token 的构造与文本预填的产出</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-8\">八 · 首块音频 token 的自回归生成</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-9\">九 · 首块送入流式声码器与波形输出</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-10\">十 · 后续块的追加与流水线并行</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-11\">十一 · 调度器的 SM 配额与显存交接</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-12\">十二 · 步骤间的耦合与工程判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-13\">十三 · 块粒度与 SM 配额：这套流水线在哪里断掉</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-14\">十四 · 前缀 KV 解码公式的逐项解剖</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-15\">十五 · 从公式到伪代码：块循环与 KV 追加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-16\">十六 · 预填与解码的 SM 配额：把抖动关进笼子</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-17\">十七 · 块间连续性的三个不变量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-18\">十八 · 显存滚动释放与长文本的规模上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-19\">十九 · 块边界上的失效面：KV 连续性、SM 配额与滚动释放</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-20\">二十 · 请求形态的匹配：文本长度与提示结构决定配方</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-21\">二十一 · 长度分布与块大小的耦合：块太短与块太长的两端代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-22\">二十二 · 并发与批大小的真实约束：SM 配额而非显存单因素</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-23\">二十三 · 负载不对时的三种失败模式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-24\">二十四 · 计费粒度与 SLO 的绑定：块数作为配方单位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-25\">二十五 · 负载配方：什么样的请求才配得上这套流水线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-26\">二十六 · 硬件档位：按首包预算反推卡型与卡数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-27\">二十七 · 并行拓扑：预填-解码流水线与声码器三级并行</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-28\">二十八 · 量化方案：FP16 主档与 KV 的精度账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-29\">二十九 · KV 策略：按块追加、滚动释放、前缀复用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-30\">三十 · 调度参数：SM 配额、队列深度与背压</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-31\">三十一 · 可复现配置思路：一张预算表串起五个旋钮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-32\">三十二 · 首包延迟的三项分解与 SM 争抢的量化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-33\">三十三 · KV 显存的线性膨胀与块滚动释放</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-34\">三十四 · 带宽：声码器流水线与 KV 读写的双重压力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-35\">三十五 · 通信：预填-解码分离后的跨设备代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-36\">三十六 · 功耗与尾延迟：批大小的收益边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-37\">三十七 · 规模上去以后先崩的顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-38\">三十八 · 预填-解码流水线的崩溃点：SM 争抢、块边界与 KV 线性膨胀</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-39\">三十九 · 精度失效：从条件 KV 污染到块边界漂移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-40\">四十 · OOM：KV 按块增长与释放时机</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-41\">四十一 · 批抖动与路由不均：SM 配额是根因</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-42\">四十二 · 尾延迟尖刺：块过长与声码器流水阻塞</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-43\">四十三 · 监控面与回滚闸门</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-44\">四十四 · 流式预填解码的失效边界与回滚判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-45\">四十五 · 对照轴：把候选算法放在同一张坐标上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-46\">四十六 · 决策表：五类候选与它们的适用条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-47\">四十七 · 同族内部的二次选择：块长与预填/解码的耦合度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-48\">四十八 · 代价对照：延迟、吞吐、显存、带宽各让一步</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-codec-lm-stream-sec-49\">四十九 · 适用条件的边界判定与切换信号</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:522px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 522.4 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"440.4\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">文本前端与说话人提示编码为条件 token，文本 LM 预填得到 KV c…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"440.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">音频 LM 以条件 KV 为前缀，按块自回归生成首块音频 token</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"440.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">首块 token 立即送入流式声码器解码为波形并播放</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"440.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">后续块继续自回归生成，KV cache 按块追加，声码器流水线并行</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"440.4\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">调度器在预填与解码间分配 SM，预填完成即释放其显存给解码 KV</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-codec-lm-stream-sec-1\">一 · 一次首包抖动事故：预填把解码饿死</h3>\n<p>先看一个在零样本 TTS 服务上真实会发生的失败形态。请求进来时，文本前端已经把整段文本与一段短说话人提示编码成条件 token，随后文本 LM 开始预填。问题出在这一步的 SM 占用：预填是一个长序列、大矩阵乘的稠密阶段，一旦调度器把它当成普通请求整批塞进 GPU，它会瞬间吃满可用的 SM 与寄存器文件。与此同时，音频 LM 的解码流正在等第一批 KV 前缀就位，好生成首块音频 token。两边没有做 SM 配额隔离，预填把解码饿死，首块 token 迟迟出不来，首包波形延迟出现秒级抖动，前端播放器只能空转等待，用户听到的是开头一段静默，随后语音突然以不自然的节奏涌出。</p>\n<p>这个事故的根因不是模型质量，而是资源竞争下的时序失控。首包延迟由三段构成：</p>\n<div class=\"formula\">$$L_{\\text{first}} = t_{\\text{prefill}} + t_{\\text{ar}}(B) + t_{\\text{voc}}(B),\\quad \\text{KV}_{\\text{audio}} \\propto B$$</div>\n<p>其中 $t_{\\text{prefill}}$ 是文本侧预填耗时，$t_{\\text{ar}}(B)$ 是生成首块 $B$ 个音频 token 的自回归耗时，$t_{\\text{voc}}(B)$ 是流式声码器把这块 token 解成波形的耗时。传统做法把三者串行压在同一个引擎里：预填不完，解码不启动；解码不完，声码器不启动。于是 $L_{\\text{first}}$ 是三者之和，而预填与解码还在争同一批 SM，$t_{\\text{prefill}}$ 与 $t_{\\text{ar}}$ 互相拖慢，和式里每一项都被放大。事故里那个“秒级抖动”，本质是 $t_{\\text{prefill}}$ 在无隔离时被拉长，并且它的尾部与 $t_{\\text{ar}}$ 重叠失败。</p>\n<p>更隐蔽的第二类失败在块边界。音频 LM 以条件 KV 为前缀按块生成，KV 按块追加。如果实现图省事，在块切换时重置了位置编码或重建了 KV 布局，$K_{a,&lt;t},V_{a,&lt;t}$ 的连续性被破坏，注意力看到的历史不再是同一条时间轴，合成语音就在块切换处出现韵律断裂或音色跳变——听感上是“换了口气”甚至“换了个人”。这类缺陷不会让服务报错，只会让主观质量掉档，排查成本极高。第三类失败是显存：KV cache 按块增长，若已完成块的显存不及时释放，长文本合成时 $\\text{KV}_{\\text{audio}}$ 随块数线性膨胀，直到 OOM。注意公式里 $\\text{KV}_{\\text{audio}} \\propto B$ 的 $B$ 是块规模，块越多、驻留越久，占用越高，这条线性关系既是可控性的来源，也是不释放就爆炸的来源。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-2\">二 · 它到底解决哪一个推理问题</h3>\n<p>把事故抽象成问题陈述：零样本 TTS 的编解码器语言模型必须先编码整段文本、再自回归生成音频 token，首包延迟天然高；并且文本预填与音频解码在同一张 GPU 上争抢 SM，使首包延迟不可控。这个算法要解的正是这两件事的耦合，而不是“让 TTS 更好听”或“让模型更小”。它的解法是把文本预填与音频 token 解码分离到不同流或不同引擎：文本侧一次预填得到 KV cache 后即完成使命，音频侧以这份 KV 为前缀，按块自回归解码并流式送声码器。首包因此只需生成首块 token，而不必等整段音频生成完。</p>\n<p>核心的计算形态是带前缀 KV 的自回归解码：</p>\n<div class=\"formula\">$$p(a_t\\mid a_{&lt;t},c)=\\mathrm{softmax}(W h_t),\\quad h_t=\\mathrm{Attn}(q_t,K_{\\text{text}}\\oplus K_{a,&lt;t},V_{\\text{text}}\\oplus V_{a,&lt;t})$$</div>\n<p>这里 $c$ 是文本与说话人条件 token，$K_{\\text{text}},V_{\\text{text}}$ 是文本预填产物，$K_{a,&lt;t},V_{a,&lt;t}$ 是已生成音频 token 的 KV，$\\oplus$ 表示沿序列维拼接。这个式子的工程含义是：文本 KV 是只读前缀，音频 KV 是可追加后缀，二者拼成一条连续注意力上下文。只要拼接保持连续，块间声学一致性就有保障；一旦拼接断裂，就是上一节说的韵律跳变。因此“分离到不同流”不是目的，目的是让前缀一次成型、后缀按块滚动，同时把两阶段的 SM 需求错峰。</p>\n<p>它带来的直接收益是首包延迟结构的改变：$L_{\\text{first}}$ 从“预填+整段自回归+整段声码”变成“预填+首块自回归+首块声码”，后两项只覆盖 $B$ 个 token 而非全序列。代价则转移到调度精度上：预填与解码争抢 SM 时必须精细分配，否则首包延迟抖动；块间一致性依赖 KV 连续性；块过长会让首包延迟回升，块过短则调度开销上升。换句话说，它把一个大而不可控的串行延迟，换成了一个小而需要调参的流水线延迟。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-3\">三 · 机制的数据流：谁先谁后、谁释放谁</h3>\n<p>按数据与资源流动顺序拆开看，这条流水线有五个咬合点。第一，文本前端与说话人提示编码为条件 token，文本 LM 预填得到 KV cache——这是一次性的稠密计算，产出只读前缀。第二，音频 LM 以条件 KV 为前缀，按块自回归生成首块音频 token；此时解码只依赖前缀与已生成后缀，不依赖文本侧继续计算。第三，首块 token 立即送入流式声码器解码为波形并播放，声码器不必等后续块。第四，后续块继续自回归生成，KV cache 按块追加，声码器与 LM 解码流水线并行——上一块在声码器里合成波形的同时，下一块在 LM 里生成 token。第五，调度器在预填与解码之间分配 SM，预填完成即释放其显存给解码 KV。最后这一点是显存账的关键：预填阶段的激活占用大，但它是一次性的；解码阶段的 KV 随块增长，是持续性的。若不及时把预填的显存还给解码，$\\text{KV}_{\\text{audio}} \\propto B$ 的线性增长就会撞上显存墙。</p>\n<p>用一个具体例子走一遍：一条数十字的文本加一句短说话人提示进来，文本 LM 预填产出前缀 KV；音频 LM 生成首块（比如数十个音频 token 量级的一块），首块立刻进流式声码器出波形，用户听到开头；随后 LM 继续生成第二块、第三块，声码器按块流水合成。整个过程中，文本侧 SM 在预填结束后退出，解码侧获得更大配额，块与块之间的 KV 追加保持同一位置编码轴。这里没有编造任何时延数字，因为决定成败的是配额与块长的相对关系，而非某个固定毫秒值。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-4\">四 · 它明确不解决什么</h3>\n<p>适用边界必须说清楚，否则会被误用。第一，它不解决“文本条件本身不够”的问题：它仍是文本条件驱动的生成式 TTS，条件 token 的质量、说话人提示的表达力决定了音色与风格的上限，流水线只优化时序，不优化条件建模。第二，它不是全双工对话模型：相对级联 ASR/LLM/TTS 它省去了多次往返，但输入仍是整段文本，不存在边听边说的交错生成；双流全双工语音对话是另一条条目的事，这里一句话指路即可。第三，它不解决长文本的显存总量问题，只把增长变成线性可控：$\\text{KV}_{\\text{audio}} \\propto B$ 意味着长文本必须按块滚动释放已完成块的显存，否则线性增长照样 OOM；它给的是“可控”，不是“免费”。第四，它不替代量化与算子优化：量化以 FP16 为主时 KV 带宽压力仍在，NVFP4/FP8 与 tcgen05 那一路的收益属于别的条目，本算法只负责把预填与解码的时序与 SM 配额摆正。</p>\n<p>还有一条容易忽略的边界：块长是算法自身的超参，不是外部给定。块过短，调度开销与块边界数量上升，SM 在预填/解码间切换频繁，首包延迟抖动反而更难压；块过长，首块自回归的 $t_{\\text{ar}}(B)$ 变大，首包延迟回升，流式播放的“流”感变弱。上限因此受 KV 显存与 SM 调度精度双重约束，而不是受模型参数量单独约束。工程判断是：先把 SM 配额隔离做对，再调块长；顺序反了，调块长只是在噪声里找局部最优。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-5\">五 · 与相邻算法的分界与选型判断</h3>\n<p>相对“整段预填后一次性自回归生成”的传统编解码器 LM，本算法的差别不在模型结构，而在把文本预填与音频解码解耦到不同流/引擎，首包只需生成首块 token；传统做法把 $L_{\\text{first}}$ 压成三段串行之和，本算法把它压成“预填+首块”两段，并把声码器与后续块并行掉。相对级联 ASR/LLM/TTS，它省去多次往返的排队与序列化开销，但依然是文本条件驱动的生成式 TTS，不承担对话状态管理。选型时看三个信号：SLO 是否以首包波形延迟与块间连续性衡量；请求形态是否为零样本 TTS（文本+短说话人提示）；批大小是否受 KV 显存与块数约束。三者都成立，才轮到本算法上场；若 SLO 只关心整段合成吞吐而不关心首包，串行整段生成反而调度更简单。</p>\n<p>最后落在一个具体机制上：调度器在预填与解码间分配 SM、预填完成即释放显存给解码 KV，这一步做不做隔离，决定了事故里那个秒级抖动是否复现。把预填当作一次性稠密阶段、把解码当作持续性低占空比阶段，两阶段用不同配额与不同显存账本，块边界保持同一位置编码轴——这三件事做对，首包延迟才是可预期的；做不对，公式里那个和式依旧会被争抢放大。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-6\">六 · 预填洪峰下的首包抖动：这套方案管什么、不管什么</h3>\n<p>线上事故的形态很固定：一个零样本 TTS 服务在长文本请求集中出现时，首包波形延迟从稳态值抖到秒级，客户端播放器反复缓冲。根因不是声码器，也不是文本前端，而是文本预填与音频自回归解码共用同一批 SM——长文本预填一次性占满 SM 与显存带宽，解码流被挤到队尾，首块音频 token 迟迟出不来。首包延迟可写成 <span class=\"formula\">$$L_{\\text{first}} = t_{\\text{prefill}} + t_{\\text{ar}}(B) + t_{\\text{voc}}(B),\\quad \\text{KV}_{\\text{audio}} \\propto B$$</span> 其中 $B$ 为首块 token 数。整段预填模式下 $t_{\\text{prefill}}$ 与 $t_{\\text{ar}}$ 串行且共享资源，任一项被争抢都会直接放大 $L_{\\text{first}}$。本方案要解决的正是这个具体问题：把文本预填与音频解码解耦到不同流/引擎，让首包只依赖首块 token 的生成与一次声码器前向。</p>\n<p>它的机制边界同样明确。文本 LM 预填得到 $K_{\\text{text}},V_{\\text{text}}$ 后即释放其显存给解码 KV，音频 LM 以条件 KV 为前缀按块解码：<span class=\"formula\">$$p(a_t\\mid a_{&lt;t},c)=\\mathrm{softmax}(W h_t),\\quad h_t=\\mathrm{Attn}(q_t,K_{\\text{text}}\\oplus K_{a,&lt;t},V_{\\text{text}}\\oplus V_{a,&lt;t})$$</span> 因此它不解决声码器本身的吞吐瓶颈，也不解决跨请求的批调度公平性——那是连续批处理与 SLO 容量规划的话题。它更不是全双工对话模型：相对级联 ASR/LLM/TTS 省去多次往返，但仍是文本条件驱动的生成式 TTS，输入必须先在文本侧闭合才能预填。</p>\n<p>失效条件集中在三处，且都对应可观测的系统代价。其一，预填与解码未做 SM 配额隔离时，长文本预填占满 SM，首包延迟出现秒级抖动，这正是事故的复现路径；调度器必须按两阶段分配 SM，并在预填完成瞬间释放显存，否则解码 KV 追加会被显存分配阻塞。其二，块边界若重置位置编码或丢弃 KV 连续性，块切换处出现韵律断裂与音色跳变，这是听感层面的稳定性代价，无法靠增加块数掩盖。其三，块过长使 $t_{\\text{ar}}(B)$ 回升、首包延迟反弹；块过短则调度开销与声码器启动次数上升。KV 显存随已生成音频长度线性增长，长文本必须按块滚动释放已完成块，否则显存线性膨胀直至 OOM——这是该方案规模上限的直接来源，而非算力上限。</p>\n<table class=\"mini\"><thead><tr><th>边界</th><th>不解决的对象</th><th>系统代价</th></tr></thead><tbody><tr><td>SM 争抢</td><td>预填洪峰下的首包抖动</td><td>需配额调度，否则秒级抖动</td></tr><tr><td>块连续性</td><td>块切换韵律断裂</td><td>KV 必须连续追加</td></tr><tr><td>块长度</td><td>首包延迟与调度开销的折中</td><td>过长延迟回升、过短开销上升</td></tr></tbody></table>\n<h3 id=\"alg-codec-lm-stream-sec-7\">七 · 条件 token 的构造与文本预填的产出</h3>\n<p>流式编解码器 LM 的第一步不是生成音频，而是把“说什么”和“谁在说”压成一段可被注意力复用的前缀。文本前端负责把输入文本切成子词并映射为 token 序列，说话人提示则经提示编码器得到固定长度的嵌入向量；两者拼接后构成条件序列 $c$。这一步的输入是原始文本与短音频提示，输出是一串条件 token 及其位置编码，代价集中在 CPU 侧的文本处理与一次提示编码的前向，量级远小于后续 LM 前向，但它决定了预填序列的长度——文本越长，预填越重。</p>\n<p>条件 token 进入文本 LM 后执行一次完整预填：所有条件 token 并行通过各层注意力，产出每一层的 $K_{\\text{text}},V_{\\text{text}}$ 并写入 KV cache。预填的输入是整段条件序列，输出是这份前缀 KV 以及最后一个位置的隐状态。代价是二次方于序列长度的注意力计算与线性于层数的权重读取，属于典型的计算密集阶段；对长文本，预填会长时间占满 SM，这正是它与音频解码争抢资源的根源。工程上预填应作为一次性、可被抢占的批处理任务提交，其显存占用在完成后立即转交解码侧。</p>\n<p>预填的产出必须满足一个约束：KV 的布局要与后续音频 KV 的追加方式兼容。若文本 KV 与音频 KV 分处不同页或不同张量，解码时每步注意力都要做一次跨区拼接，代价是额外的拷贝与不连续访存。因此在预填阶段就应按“前缀+追加”的统一布局分配 KV 页，使音频块追加只是往同一序列尾部写新页。这一步的显存代价是 $O(|c|)$ 的前缀 KV，对短提示与中等文本而言是常量级开销，不随生成音频长度增长。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-8\">八 · 首块音频 token 的自回归生成</h3>\n<p>音频 LM 以文本预填 KV 为前缀开始解码，第 $t$ 步的注意力读取拼接后的键值：</p>\n<div class=\"formula\">$$p(a_t\\mid a_{&lt;t},c)=\\mathrm{softmax}(W h_t),\\quad h_t=\\mathrm{Attn}(q_t,\\,K_{\\text{text}}\\oplus K_{a,&lt;t},\\,V_{\\text{text}}\\oplus V_{a,&lt;t})$$</div>\n<p>其中 $c$ 为条件 token，$K_{\\text{text}},V_{\\text{text}}$ 为预填产物，$K_{a,&lt;t},V_{a,&lt;t}$ 为已生成音频 token 的 KV。首块的生成以“块”为单位而非逐 token 串行到块尾才交付：块内仍是逐 token 自回归，但块的首个 token 一旦采样完成即可触发下游。输入是前缀 KV 与已生成的块内 token，输出是首块全部音频 token 及其新增 KV。代价是每 token 一次完整前向，受权重带宽约束，属于访存密集阶段；批大小 $B$ 增大时单 token 前向摊薄，但 KV 显存随之线性上升。</p>\n<p>这里的关键判断是块长度的选取。块过短，首包快但块间切换频繁，调度与声码器启停开销占比升高；块过长，首包延迟随块内 token 数线性回升，违背流式初衷。块长应取“首包 SLO 允许的最大 token 数”与“声码器最小可解码窗口”两者的较小者，并按硬件档位标定。首块生成期间，调度器必须为解码保留固定的 SM 配额，否则预填任务会把解码挤到队尾，首包延迟出现抖动。</p>\n<p>首块 token 生成完毕即写入 KV 尾部，KV 长度从 $|c|$ 增至 $|c|+n_1$。此时显存占用为前缀 KV 加首块 KV，与已生成音频长度成线性关系。若首块 token 尚未全部生成就提前送声码器，会破坏块内上下文一致性；因此交付粒度是“整块 token”，而非“单 token”，这是首包延迟与声学质量之间的第一个折中点。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-9\">九 · 首块送入流式声码器与波形输出</h3>\n<p>首块 token 离开 LM 后进入流式声码器。声码器的输入是这一块的离散码本索引序列，输出是对应时间窗的波形采样。流式声码器持有跨块的隐状态（如重叠窗或因果卷积的缓存），因此块边界不是硬切，而是带重叠的拼接。这一步的代价是声码器前向的计算与内存带宽，量级小于 LM 解码但不可忽略；它与 LM 解码可并行，因为声码器处理第 $k$ 块时，LM 已在生成第 $k+1$ 块。</p>\n<p>首包延迟由三段构成：</p>\n<div class=\"formula\">$$L_{\\text{first}} = t_{\\text{prefill}} + t_{\\text{ar}}(B) + t_{\\text{voc}}(B),\\quad \\text{KV}_{\\text{audio}} \\propto B$$</div>\n<p>预填时间由文本长度决定，自回归时间由首块 token 数与批大小决定，声码器时间由块窗长决定。三者中任何一段被资源争抢拉长，首包都会抖动。工程上的做法是把声码器放在独立流上，使其启动不依赖 LM 解码的完成信号之外的任何同步点；LM 侧只需在首块 token 就绪时发一次事件，声码器侧即可开始消费。代价是跨流同步的固定开销，通常远小于一个块的解码时间。</p>\n<p>波形一旦产出即写入播放缓冲，播放侧按采样率消费。此处存在一个隐性约束：播放缓冲的下溢会直接表现为卡顿，因此首块必须略大于最小可播放窗口，给后续块留出追赶时间。首块过大则首包延迟上升，过小则缓冲脆弱。这个窗口的标定属于容量规划的一部分，与块长选取耦合。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-10\">十 · 后续块的追加与流水线并行</h3>\n<p>首块播出后进入稳态：音频 LM 继续按块自回归，每块生成完毕即把新 token 的 KV 追加到序列尾部，声码器消费上一块。输入是不断增长的 KV 与上一块的声码器隐状态，输出是下一块 token 与下一段波形。代价分布发生变化：LM 侧每 token 的注意力读取随 KV 长度增长而变重，声码器侧保持恒定；两者并行时，总吞吐受较慢一侧约束，通常稳态下 LM 解码是瓶颈。</p>\n<p>KV 按块追加必须保持连续性，即块边界处的位置编码、注意力掩码与缓存页映射都不能重置。若在块边界重建位置索引，注意力看到的相对位置出现跳变，声码器输出的韵律在切换处断裂。实现上应把整个音频序列视为一条连续 KV 链，块只是写入的批次单位，而非语义边界。代价是 KV 页管理需要支持增量分配与尾部写，不能按块独立分配再拼接。</p>\n<p>流水线的深度由块数与在途块数决定。在途块过多会推高 KV 显存，因为已完成但未被声码器消费的块仍占着 KV；在途块过少则流水线填不满，声码器出现空转。稳态显存约为前缀 KV 加在途块 KV，与已生成音频总长度解耦——这是按块滚动释放的前提。若已完成块的 KV 不及时释放，长文本合成时显存随总时长线性膨胀直至 OOM，这是该机制最典型的失败模式。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-11\">十一 · 调度器的 SM 配额与显存交接</h3>\n<p>调度器在本机制中承担两件事：在预填与解码之间分配 SM，以及在预填完成后把其显存交接给解码 KV。输入是请求队列、各请求的阶段状态与当前显存水位，输出是每个流获得的 SM 配额与 KV 页分配。代价是调度决策本身的延迟与配额切换带来的流水线气泡；配额切得过细，切换开销吃掉收益，切得过粗，首包抖动。</p>\n<p>可行的做法是给解码侧设一个不可剥夺的最小配额，保证首块生成始终有 SM 可用；预填侧使用剩余配额并以块为单位可抢占。预填完成的判据是前缀 KV 全部落盘且最后一个位置的隐状态就绪，此时预填占用的临时激活显存立即释放，转为解码 KV 页。这个交接点的时序直接决定首包延迟的下界：交接越晚，解码启动越迟。</p>\n<p>批大小 $B$ 在此受双重约束：KV 显存约束与块数约束。$B$ 增大摊薄权重读取、提升解码吞吐，但 $\\text{KV}_{\\text{audio}} \\propto B$ 意味着在途块与批共同挤压显存。调度器需按“前缀 KV + 在途块 KV × B”估算水位，在接近上限时优先缩减在途块而非缩减批，因为缩批会直接抬高单 token 成本。这一取舍的量化依据是每 token 的权重带宽开销与 KV 读取开销之比，前者随 $B$ 摊薄，后者随序列长度上升。</p>\n<p>失败模式的形态很具体：预填长文本未做配额隔离时占满 SM，解码排队，首包延迟出现秒级抖动，播放侧缓冲下溢表现为卡顿；块边界重置位置编码则在切换处产生韵律断裂或音色跳变；KV 按块增长但未释放已完成块，长文本下显存线性膨胀至 OOM。三者分别对应调度、连续性与显存回收三个环节，任一环节失守都会让流式收益归零。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-12\">十二 · 步骤间的耦合与工程判据</h3>\n<p>把五步串起来看，耦合点有三处。第一处是预填产出与解码追加的 KV 布局必须同构，否则每步注意力都要跨区拼接，代价是拷贝与不连续访存，直接抬高 $t_{\\text{ar}}$。第二处是首块 token 的交付粒度与声码器窗口的匹配，块长选取同时影响 $L_{\\text{first}}$ 与块间连续性，属于单参数双目标。第三处是调度配额与显存交接的时序，交接点晚于首块生成需求则首包延迟失去下界保证。</p>\n<p>工程判据可以收敛为三条可检验的条件：其一，预填与解码的 SM 配额在时间上不重叠占用同一批 SM，即预填可抢占且解码有保底；其二，音频 KV 是一条连续链，块只是写入批次，位置编码与页映射在块边界不变；其三，已完成块的 KV 在声码器消费后立即回收，稳态显存只与在途块数相关而非与总时长相关。三条同时成立时，首包延迟由 $t_{\\text{prefill}}+t_{\\text{ar}}(B)+t_{\\text{voc}}(B)$ 给出可预测上界，长文本合成不会因显存膨胀而失败。</p>\n<p>反过来，若只能满足其中两条，应优先保住连续性与显存回收，牺牲部分首包延迟——因为韵律断裂与 OOM 是硬失败，而首包延迟是可被 SLO 容忍的软指标。这一优先级判断来自本机制的结构：块间连续性依赖 KV 链的物理连续，一旦破坏无法在声码器侧补救；显存回收失效则是随时长累积的确定性崩溃。首包延迟的抖动可以通过配额隔离在后续版本收敛，前两者不能。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-13\">十三 · 块粒度与 SM 配额：这套流水线在哪里断掉</h3>\n<p>分离式预填/解码的收益全部押在“首块 token 尽快出现”上，而首块延迟由三项串行时间叠加：<div class=\"formula\">$$L_{\\text{first}} = t_{\\text{prefill}} + t_{\\text{ar}}(B) + t_{\\text{voc}}(B),\\quad \\text{KV}_{\\text{audio}} \\propto B$$</div>其中 $B$ 为首块 token 数。块长 $B$ 是一个双向旋钮：$B$ 增大使 $t_{\\text{ar}}$ 与 $t_{\\text{voc}}$ 同时变长、首包推迟，但块过短则每块都要重入调度器、重取 KV 前缀、重发一次声码器 kernel launch，调度开销按块数线性累积。工程上应把 $B$ 定在“声码器一次前向能覆盖的最短波形时长”附近，让 $t_{\\text{voc}}(B)$ 与 $t_{\\text{ar}}(B)$ 大致同量级，使两者在流水线中真正重叠而不是互相等待。这条边界不是调参问题而是结构问题：一旦 $B$ 小于声码器的最小感受野，块切换处的声学上下文被截断，KV 连续性再完美也补不回韵律。</p>\n<p>第二个失效条件是 SM 争抢。文本预填是长序列、高算术强度的稠密计算，音频解码是逐 token、低算术强度、受 KV 带宽约束的访存型负载，两者混跑在同一组 SM 上时，预填会以占用率优势挤掉解码的 warp，首包延迟出现秒级抖动、流式播放卡顿。可行做法是给两阶段划硬配额：预填独占一部分 SM 并在完成后立即释放其显存给解码 KV，解码侧保留固定 SM 数以维持 token 间节拍。代价是预填吞吐下降——被让出的 SM 在预填期间闲置，整段文本的编码时间变长，这与“首包快”是直接 trade-off，调度器必须按 SLO 而非按 GPU 利用率做决策。</p>\n<p>第三个代价在显存侧。KV 按块追加使占用与已生成音频长度线性相关，长文本合成若不滚动释放已完成块的 KV，占用会单调膨胀直至 OOM；释放又必须保留块边界处的少量重叠 token 以维持 $K_{\\text{text}}\\oplus K_{a,&lt;t}$ 的连续性，否则块切换处出现音色跳变。因此每块的净显存增量是“新增 KV 减去可释放旧块 KV”，滚动窗口大小决定了并发批上限，也决定了计费粒度——按块计费意味着块数即成本单位，块越短计费越细但调度开销越高。适用边界由此清晰：它适合零样本 TTS 的低首包延迟场景，上限受 KV 显存与 SM 调度精度共同约束，而非受算力约束。</p>\n<h3 id=\"alg-codec-lm-stream-sec-14\">十四 · 前缀 KV 解码公式的逐项解剖</h3>\n<p>本片段要落到可实现的程度，所以从那条核心公式开始逐项拆。带前缀 KV 的自回归解码写作：</p>\n<div class=\"formula\">$$p(a_t\\mid a_{&lt;t},c)=\\mathrm{softmax}(W h_t),\\quad h_t=\\mathrm{Attn}(q_t,K_{\\text{text}}\\oplus K_{a,&lt;t},V_{\\text{text}}\\oplus V_{a,&lt;t})$$</div>\n<p>四个符号各自对应一段真实的显存与算力开销。$c$ 是文本与说话人条件 token，它在进入音频 LM 之前已经被文本侧引擎消化成 KV，因此 $c$ 本身在音频解码阶段不再参与前向计算，只以 $K_{\\text{text}},V_{\\text{text}}$ 的形式存在。$K_{\\text{text}},V_{\\text{text}}$ 是文本预填的产物，其形状由文本长度与层数决定，是解码阶段最稳定的显存基底——它不随音频增长，但也不能被逐块释放，除非做前缀重算。$K_{a,&lt;t},V_{a,&lt;t}$ 是已生成音频 token 的 KV，随块追加而线性增长，是显存里唯一随时间膨胀的部分。$a_t$ 是第 $t$ 个音频 token，其词表大小直接决定 $W h_t$ 这一步的带宽压力。</p>\n<p>推导的关键一步在拼接（$\\oplus$）而不是重算。注意力对键值序列的拼接是结合性的：把文本 KV 与音频 KV 沿序列维拼成一个更长的 $K,V$，查询 $q_t$ 只与这个拼接后的序列做一次 softmax 归一化。这意味着文本条件不是通过修改 $q_t$ 注入的，而是通过扩展被注意的键值集合注入的。工程含义很直接：音频侧解码器只需维护一个逻辑上连续的 KV 缓冲，文本段只读、音频段追加，块边界处不重置位置编码，$a_{&lt;t}$ 的索引在拼接序列上连续递增。一旦在块边界把音频 KV 当成新序列重新起编号，拼接就退化成两段独立注意力，公式里的 $\\oplus$ 不再成立，韵律断裂正是从这里来的。</p>\n<p>代价侧：$W h_t$ 是每步都要付的固定带宽账单，词表越大越贵，且与批大小 $B$ 成正比；注意力部分的开销随 $t$ 增长，但因为文本 KV 只读，它的增长斜率只由音频段决定。首包延迟公式把这三段拆开：</p>\n<div class=\"formula\">$$L_{\\text{first}} = t_{\\text{prefill}} + t_{\\text{ar}}(B) + t_{\\text{voc}}(B),\\quad \\text{KV}_{\\text{audio}} \\propto B$$</div>\n<p>$t_{\\text{prefill}}$ 是文本侧一次前向的耗时，与文本长度相关而与 $B$ 弱相关；$t_{\\text{ar}}(B)$ 是生成首块全部音频 token 的自回归步数乘以单步耗时，单步耗时里就含上面那个 $W h_t$；$t_{\\text{voc}}(B)$ 是首块 token 送入流式声码器到出第一段波形的耗时。$\\text{KV}_{\\text{audio}} \\propto B$ 这一项说明批大小不是免费的：每加一个请求，音频 KV 就多一份，而文本 KV 在预填完成后若被共享（同一文本多说话人）则可摊薄。举例：一段中等长度文本预填后，若首块定为数十个音频 token，则 $t_{\\text{ar}}$ 由这几十步解码构成，$t_{\\text{voc}}$ 只处理这几十个 token 对应的波形帧，两者叠加才是用户听到的第一个音素的时间。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-15\">十五 · 从公式到伪代码：块循环与 KV 追加</h3>\n<p>把公式落成可实现的控制流，核心是一个外层块循环套内层 token 循环，KV 缓冲在块之间只追加不重建。伪代码思路如下：</p>\n<ul>\n<li>预填阶段：文本前端产出条件 token 序列，文本 LM 一次前向写入 $K_{\\text{text}},V_{\\text{text}}$ 到共享 KV 缓冲的头部，记录文本段长度 $n_{\\text{text}}$ 与位置偏移。</li>\n<li>初始化音频段：把音频 KV 缓冲的写指针置于 $n_{\\text{text}}$，位置编码从 $n_{\\text{text}}$ 起连续编号，保证拼接语义。</li>\n<li>块循环：对第 $k$ 块，循环 $n_{\\text{blk}}$ 步，每步以当前 $q_t$ 对 $[0,\\,n_{\\text{text}}+t)$ 的拼接 KV 做注意力，采样 $a_t$，把新 token 的 $K,V$ 写到写指针处并前移。</li>\n<li>块内不等待：首块一旦攒满 $n_{\\text{blk}}$ 个 token 就立即交给流式声码器，不等后续块。</li>\n<li>声码器侧：以块为单位接收 token，维护自己的重叠上下文（前后块各取若干帧做交叠），输出波形片段并推流。</li>\n<li>释放：块 $k$ 的波形确认播放后，若采用滚动窗口，则把 $k$ 之前过老的音频 KV 标记为可回收，只保留声码器重叠所需的最短历史。</li>\n</ul>\n<p>这里有两个容易写错的实现细节。第一，采样必须用块内已追加的 KV，而不是块开始时拍下的快照——否则块内 token 之间失去因果依赖，公式里的 $a_{&lt;t}$ 就名不副实。第二，位置编码的连续性必须由写指针统一管理，不能让文本段和音频段各自维护一套偏移再在注意力里做掩码拼接，那样每次前向都要多一次索引重排，在 $B$ 较大时这项开销会体现在 $t_{\\text{ar}}(B)$ 上。</p>\n<p>代价判断：块长 $n_{\\text{blk}}$ 是这条流水线唯一的手调旋钮。块短则首包快，但每块的固定开销（调度、声码器启动、交叠上下文重建）被摊到更少的 token 上，单位 token 成本上升；块长则首包慢，$t_{\\text{ar}}$ 随 $n_{\\text{blk}}$ 线性上升。工程上应让 $n_{\\text{blk}}$ 与声码器的感受野对齐，使交叠帧数刚好覆盖块边界，避免为对齐而额外拉长块。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-16\">十六 · 预填与解码的 SM 配额：把抖动关进笼子</h3>\n<p>公式里 $t_{\\text{prefill}}$ 与 $t_{\\text{ar}}(B)$ 是相加关系，但在同一 GPU 上它们是竞争关系。若不做隔离，长文本预填会占满 SM，解码步被挤到队尾，$t_{\\text{ar}}$ 的实际值远超其标称值，首包延迟出现秒级抖动，流式播放卡顿。可实现的隔离手段是给两阶段划 SM 配额：预填引擎持有固定比例的 SM 与显存池，解码引擎持有另一份，二者通过流或独立引擎边界隔开，调度器只在配额内调度。</p>\n<p>配额推导的关键一步是算清预填的显存释放时点。预填完成后，文本 LM 的中间激活可以立即释放，但 $K_{\\text{text}},V_{\\text{text}}$ 必须保留给解码。因此“预填完成即释放其显存给解码 KV”释放的是激活与临时缓冲，不是前缀 KV 本身。这一点决定了显存预算的形状：常驻部分是前缀 KV 加解码引擎的固定开销，增长部分是 $\\text{KV}_{\\text{audio}}\\propto B$。若把前缀 KV 也误当作可释放，解码第一步就会触发重算，$t_{\\text{prefill}}$ 被二次计入首包延迟。</p>\n<p>具体例子：一个批里混有长短差异很大的文本请求时，若不隔离，短文本请求的首包会被长文本预填拖住；隔离后，短文本请求的预填在自己的配额里快速完成，解码侧配额始终有 SM 可用，首包延迟的方差被压到与块长同量级。代价是隔离会牺牲一部分峰值吞吐——预填配额空闲时不能借给解码做大批量——这是用吞吐换延迟确定性的典型取舍。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-17\">十七 · 块间连续性的三个不变量</h3>\n<p>块切换处的韵律不连续不是声码器的问题，而是 KV 语义被破坏的症状。要保持公式成立，需守住三个不变量。</p>\n<ul>\n<li>位置连续：音频 token 的位置编号跨块单调递增，块边界不重置。这是 $\\oplus$ 成立的前提。</li>\n<li>KV 只追加：块 $k+1$ 的注意力必须能看到块 $k$ 写入的全部 $K,V$，不允许因缓冲复用而覆盖未过期的历史。</li>\n<li>采样状态连续：若解码使用温度、top-k 等状态或任何跨步的随机数流，块边界不得重置，否则块首几个 token 的分布会偏移，听感上是音色跳变。</li>\n</ul>\n<p>验证手段可以很轻：在块边界处比较相邻两步的注意力输出范数与采样分布的熵，若出现阶跃式变化，说明某个不变量被破坏。代价侧，保持连续意味着不能对音频 KV 做无差别压缩——任何对历史 KV 的量化或丢弃都会在块边界放大成可听的接缝，因此滚动释放只能发生在声码器重叠窗口之外的老段上。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-18\">十八 · 显存滚动释放与长文本的规模上限</h3>\n<p>$\\text{KV}_{\\text{audio}}\\propto B$ 且随已生成音频长度线性增长，长文本合成若不做滚动释放，显存线性膨胀直至 OOM。可实现的释放策略是窗口式：保留最近 $W$ 个 token 的音频 KV 供注意力使用，更老的段在声码器重叠窗口确认后回收。窗口大小由声码器感受野与注意力有效跨度共同决定，取二者较大者再加余量。</p>\n<p>代价是注意力精度：窗口截断会让 $h_t$ 失去远距离上下文，长句的韵律一致性下降。缓解办法是把被回收段的 KV 做低比特摘要保留（例如只留均值化的键向量），在窗口外做粗粒度注意力，代价是每步多一次小规模读取，体现在 $t_{\\text{ar}}$ 上但远小于全量 KV 的带宽。规模上限因此由三件事共同决定：前缀 KV 的常驻占用、窗口大小乘以 $B$ 的增长项、以及 SM 配额下预填与解码的可调度余量。块过短会增加调度开销并放大固定成本，块过长则直接抬高 $L_{\\text{first}}$ 中的 $t_{\\text{ar}}$ 项，二者之间没有免费的最优点，只能按 SLO 反推。</p>\n<p>工程判断落在计费粒度上：块数决定计费粒度，也就决定了调度器愿意为多细的块付调度开销。当 SLO 以首包波形延迟与块间连续性衡量时，块长的选择实际上是延迟目标与连续性目标之间的显式权衡，而不是一个可以拍脑袋定的常数。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-19\">十九 · 块边界上的失效面：KV 连续性、SM 配额与滚动释放</h3>\n<p>把首包延迟公式拆开看，真正决定流式可用性的不是 $t_{\\text{prefill}}$ 的绝对值，而是它与 $t_{\\text{ar}}(B)$ 的相对量级。$L_{\\text{first}} = t_{\\text{prefill}} + t_{\\text{ar}}(B) + t_{\\text{voc}}(B)$ 中，$t_{\\text{ar}}(B)$ 随块大小 $B$ 单调上升，$t_{\\text{voc}}(B)$ 则受声码器感受野约束，块过小时声码器需要跨块拼接上下文、流水启动开销占比升高；块过大时 $t_{\\text{ar}}(B)$ 又吃掉解耦带来的全部收益。工程上 $B$ 的选取应使 $t_{\\text{ar}}(B)$ 与 $t_{\\text{voc}}(B)$ 大致同阶，让声码器与 LM 解码两条流水线重叠后不出现一侧空转。而 $\\text{KV}_{\\text{audio}} \\propto B$ 只在单块内成立，跨块累计时显存随已生成音频长度线性增长，这正是滚动释放必须介入的地方——已完成块的 KV 若不显式回收，长文本合成会在块数累积后撞上显存上限。</p>\n<p>前缀拼接的注意力形式给出连续性约束的关键一步：$h_t=\\mathrm{Attn}(q_t,\\,K_{\\text{text}}\\oplus K_{a,&lt;t},\\,V_{\\text{text}}\\oplus V_{a,&lt;t})$。拼接要求 $K_{a,&lt;t}$ 的位置编码在块切换处保持全局单调，若在块边界重置位置编码或重新分配 KV 槽位，$q_t$ 与历史键的相对位置关系被破坏，注意力分布突变，表现为块切换处的韵律断裂或音色跳变。因此块追加必须是“同一 KV 序列的尾部扩展”，而非“新建一段 KV 再拼接”。伪代码上，解码循环应写成：<ul><li>以 $K_{\\text{text}},V_{\\text{text}}$ 为固定前缀初始化音频 KV 区；</li><li>对每个块，循环 $t$ 生成 $a_t$，每步将新 $k_t,v_t$ 追加到同一 KV 区的偏移位置，位置编号全局递增；</li><li>块生成完毕立即把该块 token 推入声码器队列，同时保留其 KV 供后续块注意力使用；</li><li>仅当某块的 KV 已超出后续注意力窗口（或显式设定保留深度）时才释放对应槽位。</li></ul>释放策略与保留深度是一对矛盾：保留越深，跨块声学一致性越好，显存代价越高。</p>\n<p>SM 争抢是第二个失效面。预填长文本时文本 LM 的 GEMM 会占满可用 SM，音频解码的逐 token 小算子被挤到队尾，首包延迟出现秒级抖动、流式播放卡顿。调度器必须按阶段做配额隔离：为预填保留固定 SM 份额并设定其完成即释放显存的硬边界，把释放出的显存直接划给解码 KV 区，而不是留给下一请求的预填。代价是预填吞吐被压低——单请求预填时间拉长，但在零样本 TTS 的请求形态（文本+短说话人提示）下，预填计算量有限，牺牲的吞吐换来的首包确定性更值钱。反之若不做隔离，预填与解码在同一 SM 池内自由竞争，首包延迟的方差会大到无法用 SLO 约束。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>触发机制</th><th>系统代价</th></tr></thead><tbody><tr><td>块过长</td><td>$t_{\\text{ar}}(B)$ 主导首包</td><td>首包延迟回升，解耦收益归零</td></tr><tr><td>块过短</td><td>声码器流水启动开销与调度切换频繁</td><td>调度开销占比升高，吞吐下降</td></tr><tr><td>KV 未滚动释放</td><td>$\\text{KV}_{\\text{audio}}$ 随块数线性累积</td><td>长文本显存膨胀直至 OOM</td></tr><tr><td>块边界重置位置编码</td><td>注意力相对位置断裂</td><td>韵律不连续、音色跳变</td></tr><tr><td>无 SM 配额隔离</td><td>预填 GEMM 占满 SM</td><td>首包秒级抖动、播放卡顿</td></tr></tbody></table>\n<p>边界由此清晰：该方案适合零样本 TTS 的低首包场景，上限由 KV 显存与 SM 调度精度共同约束，长文本必须按块滚动释放而非一次性保留全部历史。判断一个实现是否踩线，看两件事——块切换处位置编号是否全局连续、预填完成到解码 KV 分配之间是否存在显存空窗。前者决定声学连续性，后者决定首包抖动幅度；两者都不在公式里，却直接决定 $L_{\\text{first}}$ 的可预测性。</p>\n<h3 id=\"alg-codec-lm-stream-sec-20\">二十 · 请求形态的匹配：文本长度与提示结构决定配方</h3>\n<p>流式编解码器 LM 的负载配方不是从并发数出发的，而是从请求内部的<strong>文本长度分布</strong>出发。零样本 TTS 请求由两段组成：文本前端产出的条件 token 序列，以及一段短说话人提示编码出的音色条件。文本侧的长度直接决定预填阶段占用的 SM 时间与 KV 显存，音频侧的长度则决定解码阶段的块数与 KV 增长曲线。二者在同一个请求内是串联的，但在 GPU 上必须被拆成两条资源需求曲线：预填是<em>一次性、突发、带宽密集</em>的矩阵乘；解码是<em>持续、低占用、延迟敏感</em>的逐 token 自回归。配方要回答的第一个问题是：这个请求的文本预填能否在首块音频 token 生成之前完成，并且不把解码侧的 SM 配额挤掉。</p>\n<p>用前文的公式看，首包延迟由三段构成：</p>\n<div class=\"formula\">$$L_{\\text{first}} = t_{\\text{prefill}} + t_{\\text{ar}}(B) + t_{\\text{voc}}(B),\\quad \\text{KV}_{\\text{audio}} \\propto B$$</div>\n<p>其中 $B$ 是首块 token 数。注意 $t_{\\text{prefill}}$ 随文本长度近似线性增长，而 $t_{\\text{ar}}(B)$ 与 $t_{\\text{voc}}(B)$ 随块大小增长。这意味着配方存在一个<strong>文本长度上限</strong>：当文本 token 数超过某个阈值，预填本身就会吃掉首包预算的大半，此时无论块怎么切，首包延迟都无法压到 SLO 以内。工程判断是：把长文本请求从低延迟流式通道里分流出去，走“预填优先、允许首包放宽”的另一条队列，而不是在同一队列里靠调块大小硬扛。</p>\n<p>具体例子：一段数百字的旁白文本，其条件 token 序列远长于一句短对白。前者预填占用 SM 的时间是后者的数倍，若与短请求混在同一批里，短请求的首包会被长请求的预填拖住。配方上应把文本长度作为<strong>分桶键</strong>，而不是把并发数当唯一调度维度。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-21\">二十一 · 长度分布与块大小的耦合：块太短与块太长的两端代价</h3>\n<p>块大小 $B$ 是这套机制里最敏感的参数，因为它同时出现在首包延迟公式的两项里，又反向约束 KV 显存。块过短，$t_{\\text{ar}}(B)$ 与 $t_{\\text{voc}}(B)$ 单次开销小，但块数增多，调度器在预填与解码之间切换 SM 配额的次数上升，每次切换都有固定开销与流水线气泡；块过长，首包要等更多 token 生成完才送声码器，$L_{\\text{first}}$ 直接回升。配方要按<strong>文本长度分布的分位数</strong>而不是均值来选块：短文本请求占多数时，块应偏小以压首包；长文本请求占多数时，块可偏大以减少切换开销，但必须接受首包变长。</p>\n<p>KV 显存的约束是硬的：$\\text{KV}_{\\text{audio}} \\propto B$ 只在单块意义上成立，跨块累积后显存与已生成音频长度线性相关。批大小因此不能独立设定，它由“每请求 KV 增长速率 × 预期音频时长 × 并发数”共同决定。一个可操作的伪代码思路是：</p>\n<ul>\n<li>按文本 token 数把请求分入短/中/长三桶，每桶独立设定 $B$ 与最大并发；</li>\n<li>对每桶估算单请求峰值 KV：$\\text{KV}_{\\text{peak}} = \\text{KV}_{\\text{text}} + k \\cdot T_{\\text{audio,max}}$，$k$ 为每 token KV 字节数；</li>\n<li>批大小上限 $= \\lfloor \\text{可用显存} / \\text{KV}_{\\text{peak}} \\rfloor$，再与 SM 配额能支撑的解码并发取小；</li>\n<li>块数决定计费粒度，长音频请求按块滚动释放已完成块的 KV，避免显存线性膨胀。</li>\n</ul>\n<p>代价面：块切换处的声学一致性依赖 KV 连续性，块边界若重置位置编码或丢弃历史 KV，合成语音会出现韵律断裂或音色跳变。这是配方必须用“KV 按块追加、不重置”来换取的稳定性，代价是显存不能立即回收，只能滚动释放。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-22\">二十二 · 并发与批大小的真实约束：SM 配额而非显存单因素</h3>\n<p>很多人会把批大小直接算成显存除法，但在这套预填-解码流水线里，真正的瓶颈往往是<strong>SM 配额</strong>。文本预填是突发的大矩阵乘，会瞬间占满可用 SM；音频解码是逐 token 的低占用操作，却对延迟极度敏感。若不做配额隔离，一个长文本预填就能把解码侧饿死，首包延迟出现秒级抖动，流式播放卡顿。配方的核心动作是把 SM 切成两份配额：预填配额与解码配额，并让预填完成即释放其显存给解码 KV。并发数因此不是“能塞多少请求”，而是“解码配额能同时养活多少条自回归流”。</p>\n<p>公式上可写成约束：设解码每 token 需要 $s_d$ 个 SM 单元、每 token 耗时 $t_d$，则并发 $N$ 条流要满足 $N \\cdot s_d \\le S_{\\text{decode}}$，且单流块间间隔 $B \\cdot t_d$ 必须小于声码器流水线的消费周期，否则声码器空转。预填侧则要求 $S_{\\text{prefill}}$ 足够大使 $t_{\\text{prefill}}$ 落在首包预算内。两侧配额之和不超过总 SM，这就是配方的可行域。</p>\n<p>具体例子：当并发从个位数升到数十条时，解码配额先饱和，表现为块间间隔拉长、声码器欠载；此时加并发只会增加排队，不会增加吞吐。正确做法是提高块大小以减少切换、或把部分请求分流到独立引擎，而不是继续堆批。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-23\">二十三 · 负载不对时的三种失败模式</h3>\n<p>失败模式一：<strong>预填与解码未做 SM 配额隔离</strong>。长文本预填占满 SM，解码侧拿不到算力，首包延迟抖动到秒级，流式播放卡顿。这不是偶发，而是配方缺了隔离这一层的必然结果。失败模式二：<strong>块间 KV 追加未保持连续性</strong>，例如块边界重置位置编码，合成语音在切换处出现韵律断裂或音色跳变；听感上表现为句中断气或音色漂移，SLO 里的“块间连续性”指标直接破防。失败模式三：<strong>KV 按块增长但未及时释放已完成块的显存</strong>，长文本合成时显存线性膨胀直至 OOM；这类失败在短请求压测里完全看不出来，只在长音频、高并发叠加时暴露。</p>\n<p>三种失败对应三种配方修正：配额隔离解决抖动，KV 连续追加解决韵律，滚动释放解决 OOM。三者不能互相替代——只做配额隔离而不滚动释放，长文本仍会 OOM；只滚动释放而不保连续性，音质仍会断裂。配方必须同时满足，代价是调度器复杂度上升与显存回收的时机判断。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-24\">二十四 · 计费粒度与 SLO 的绑定：块数作为配方单位</h3>\n<p>这套机制的 SLO 不是单一的端到端延迟，而是<strong>首包波形延迟</strong>加<strong>块间连续性</strong>两个指标。首包延迟由 $L_{\\text{first}}$ 决定，块间连续性由 KV 追加策略决定。配方把块数当作计费粒度：一个请求消耗的算力大致正比于块数 × 每块解码开销，预填开销单独计。这样容量规划就能按“每块成本 × 预期块数分布”估算，而不是按请求数拍脑袋。</p>\n<p>工程判断落在具体机制上：把文本长度分桶、块大小按桶设定、SM 配额按预填/解码两阶段切分、KV 按块追加并滚动释放，这四件事共同构成负载配方的可行域。负载不对时，症状会精确地落在首包抖动、韵律断裂、显存膨胀三者之一；反过来，看到这三种症状，就能定位到配方里缺了哪一层。块数决定计费粒度这一条，还意味着容量规划必须按块数分布而非请求数分布来做——短请求多不等于负载轻，长音频请求的块数才是显存与 SM 时间的主要消耗者。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-25\">二十五 · 负载配方：什么样的请求才配得上这套流水线</h3>\n<p>这套方案的收益不是无条件成立的，它的负载配方相当窄：请求形态必须是零样本 TTS——一段文本加一段短说话人提示，输出是单条连续音频流，而不是多轮对话、不是批量朗读、也不是需要边听边答的全双工交互。文本长度分布决定了预填阶段的绝对耗时，而首包延迟由 <span class=\"formula\">$$L_{\\text{first}} = t_{\\text{prefill}} + t_{\\text{ar}}(B) + t_{\\text{voc}}(B)$$</span> 三项叠加构成，其中 $B$ 是首块音频 token 数。注意 $t_{\\text{prefill}}$ 随文本长度增长，$t_{\\text{ar}}(B)$ 与 $t_{\\text{voc}}(B)$ 随块大小增长，三者不是可以互相抵消的项——把块调小能压 $t_{\\text{ar}}$ 和 $t_{\\text{voc}}$，却把调度开销和块切换次数推高；把块调大能让声码器流水线吃得更饱，首包却直接变慢。因此块大小本质上是首包延迟与块间开销之间的一个显式取舍参数，而不是可以随手设的默认值。并发与批大小同样受约束：$\\text{KV}_{\\text{audio}} \\propto B$，批内每条请求的音频 KV 都随已生成长度线性增长，批大小实际上是被 KV 显存和块数共同卡死的，而不是被算力卡死的。</p>\n<p>负载一旦偏离这个配方，失效是结构性的而非性能上的轻微退化。最典型的是长文本请求：文本预填与音频解码若未做 SM 配额隔离，预填长文本会占满 SM，首包延迟出现秒级抖动，流式播放直接卡顿——这不是平均延迟变差，而是首包这个 SLO 指标本身失守，用户感知为“点了没反应”。第二种是块边界处理不当：块间声学一致性完全依赖 KV 连续性，若在块边界重置位置编码或重建 KV，合成语音会在块切换处出现韵律断裂或音色跳变，首包再快也救不回来。第三种是长文本合成时 KV cache 按块增长却未及时释放已完成块的显存，显存线性膨胀直至 OOM；调度器“预填完成即释放其显存给解码 KV”这条规则必须落实到块粒度，否则显存曲线就是单调上升的斜线。三类失效对应三个不同的系统代价：延迟抖动打的是 SLO，韵律断裂打的是质量，OOM 打的是容量上限。</p>\n<p>把负载特征与方案能力对齐，可以用一张小表快速判断请求是否落在配方内：</p>\n<table class=\"mini\"><thead><tr><th>负载维度</th><th>配方内</th><th>越界后的主代价</th></tr></thead><tbody><tr><td>请求形态</td><td>零样本 TTS，文本+短说话人提示</td><td>多轮/全双工需跨请求保持 KV，块模型不成立</td></tr><tr><td>文本长度</td><td>中等长度，预填可被配额限制</td><td>长文本预填占满 SM，首包秒级抖动</td></tr><tr><td>块大小</td><td>块数适中，首块尽量短</td><td>块过短调度开销升，块过长首包延迟回升</td></tr><tr><td>并发/批大小</td><td>受 KV 显存与块数约束的小批</td><td>批过大触发 KV 线性膨胀与 OOM</td></tr></tbody></table>\n<p>工程判断上，这套流水线的适用边界由两个量共同划定：KV 显存随已生成音频长度的线性增长斜率，以及调度器在预填与解码之间分配 SM 的精度。前者决定单条请求能合成多长、能并发多少条；后者决定首包延迟的方差而不是均值。块数还顺带决定了计费粒度——按块计费意味着短请求的单位成本偏高，长请求的单位成本被摊薄，这与“块过长首包延迟上升”的约束形成对冲。因此上线前应先测的是首包延迟的分布尾部与块切换处的听感一致性，而不是平均吞吐；前者对应 SM 配额调度的鲁棒性，后者对应 KV 追加是否严格连续。当请求形态稳定落在零样本 TTS、文本长度可控、块大小经过实测标定这三个条件同时满足时，这套解耦流水线才真正把“首包只需生成首块 token”的优势兑现为可承诺的 SLO。</p>\n<h3 id=\"alg-codec-lm-stream-sec-26\">二十六 · 硬件档位：按首包预算反推卡型与卡数</h3>\n<p>部署配方的第一步不是选最大卡，而是把首包延迟预算拆成三段：文本预填、首块自回归、首块声码器。前文给出的 $$L_{\\text{first}} = t_{\\text{prefill}} + t_{\\text{ar}}(B) + t_{\\text{voc}}(B)$$ 是唯一的约束式，硬件档位必须让三段都落在预算内且互不挤占。工程判断是：文本预填是长序列、低并行度的注意力密集型负载，吃的是单卡 SM 与显存带宽；音频解码是短序列、高频次的访存密集型负载，吃的是 KV 读取带宽与调度精度。两者对硬件的偏好不同，因此档位选择应看“能否把预填与解码放到物理隔离的资源域”，而不是看单卡峰值算力。</p>\n<p>具体机制上，服务端 GPU 档位分三档落地。单卡档：文本 LM 与音频 LM 同卡不同 CUDA 流，靠 SM 配额切分（如预填占用固定比例的 SM，解码占用剩余），适合短文本、低并发，代价是预填长文本时解码流被饿死，首包抖动。双卡档：文本预填引擎与音频解码引擎分置两卡，KV 前缀通过 NVLink 或主机侧拷贝传递，预填完成即释放其显存给解码 KV，这是最稳的档位，代价是多一跳 KV 传输延迟与一张卡的静态占用。分离档：预填与解码分属不同实例甚至不同节点，走 NIXL 做 KV 搬运，适合高并发多租户，代价是传输链路成为首包预算里的固定项。三档的共同点是：预填侧要留出足够 SM 让长文本预填不超时，解码侧要留出足够 SM 让块间解码不排队。</p>\n<p>一个具体例子：零样本 TTS 请求文本约数百 token、说话人提示为短音频嵌入。若单卡档下预填占满 SM，解码流只能等预填结束才拿到 SM，首包延迟出现秒级抖动、流式播放卡顿——这正是已知失败模式。把预填与解码拆到两卡后，预填侧独占其 SM 完成 KV 构建，解码侧在预填进行中即可用已就绪的条件 KV 前缀启动首块生成，首包预算被切成可并行两段。代价是 KV 前缀跨卡传输占用 NVLink 带宽，且预填卡在空闲期利用率低，容量规划时要把这部分算进成本。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-27\">二十七 · 并行拓扑：预填-解码流水线与声码器三级并行</h3>\n<p>拓扑不是“张量并行越大越好”。编解码器 LM 的音频侧自回归是逐 token 的，张量并行带来的每步 all-reduce 会直接叠加到块内 token 间隔上；文本预填则是长序列一次前向，张量并行收益明显。因此拓扑应按阶段分别定：文本预填用张量并行（TP）扩到多卡以压短 $t_{\\text{prefill}}$，音频解码用数据并行（DP）复制多份引擎以提吞吐，声码器独立成第三级、与 LM 解码流水并行。三级之间用队列解耦：解码引擎产出首块 token 立即入声码器队列，声码器在另一组 SM 上分块合成，LM 继续生成下一块。</p>\n<p>伪代码思路如下：调度器维护两个 SM 配额池，预填池与解码池；请求到达后先在预填池排队，预填完成把 KV 前缀句柄交给解码池并释放预填池显存；解码池按块循环“取前缀 KV → 自回归生成一块 → 追加 KV → 首块立即投递声码器队列”；声码器池按到达顺序分块合成，块边界用连续 KV 保证韵律。关键约束是块大小 $b$：块过短则调度与队列开销占比升高，块过长则首块 token 数变多、$t_{\\text{ar}}(B)$ 上升使首包延迟回升。块大小应取“首块 token 数 × 单 token 解码步时间”刚好落在首包预算剩余额度内的最大值。</p>\n<p>系统代价上，三级流水把端到端延迟从“预填+全段生成+全段合成”压到“预填+首块生成+首块合成”，但吞吐受最慢一级约束：若声码器分块合成的实时率低于 LM 解码出块速率，队列积压，后续块播放卡顿；反之声码器空闲浪费 SM。容量规划要按“解码出块速率 ≈ 声码器实时率”配平两级 SM 比例。一个具体例子：双流场景下文本预填与音频解码本就分属不同引擎，拓扑上把预填 TP 到两卡、解码 DP 复制两份、声码器单独一组 SM，三级队列长度设上限以背压，避免长文本请求把解码池占满导致新请求首包排队。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-28\">二十八 · 量化方案：FP16 主档与 KV 的精度账</h3>\n<p>本算法的量化主档是 FP16，理由不在算力而在数值稳定性：音频 token 的自回归分布对 logits 扰动敏感，低比特权重量化在码本较大时容易让采样分布尾部失真，表现为音色漂移或韵律抖动。因此权重与激活保持 FP16，量化收益主要从 KV cache 上取。KV 是显存大头，且 $$\\text{KV}_{\\text{audio}} \\propto B$$ 说明其随批大小与已生成音频长度线性增长；把 KV 压到 FP8 能把这部分显存减半，代价是注意力读取时的反量化开销与块间精度累积误差。</p>\n<p>机制上，量化方案要分三处分别决策：文本 LM 权重可尝试 FP8（预填是一次性长前向，误差不跨步累积），音频 LM 权重保持 FP16（逐 token 累积），KV cache 用 FP8 存储、FP16 计算，按块追加时对块边界做一次尺度对齐以避免块切换处的数值跳变。声码器侧通常保持 FP16，分块合成对波形相位敏感，低比特量化易在块边界产生可听噪声。系统代价：FP8 KV 使显存占用下降、可支撑更大批或更长音频，但注意力读取需反量化，单 token 解码步时间上升；若解码是访存瓶颈，这部分开销会被带宽节省部分抵消，净收益取决于块内 token 数与 KV 读取量之比。</p>\n<p>一个具体例子：长文本合成时 KV 按块增长，若 KV 用 FP16 且不及时释放已完成块，显存线性膨胀直至 OOM——已知失败模式。改用 FP8 KV 并把已完成块的 KV 滚动释放，显存曲线从单调上升变为按块锯齿，峰值由“当前活跃块数 × 块 KV 大小”决定，容量规划据此定批大小上限。注意块边界尺度对齐若省略，块切换处会出现韵律断裂或音色跳变，这与 KV 不连续是同一类失败。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-29\">二十九 · KV 策略：按块追加、滚动释放、前缀复用</h3>\n<p>KV 策略是本部署配方里最影响成本的一项。文本预填得到的 $K_{\\text{text}},V_{\\text{text}}$ 是条件前缀，对同一说话人提示与文本可复用；音频侧 $K_{a,&lt;t},V_{a,&lt;t}$ 按块追加，必须保持连续性——块边界重置位置编码会直接破坏注意力上下文，产生韵律断裂。策略分三层：前缀 KV 缓存池（按文本+说话人提示哈希复用，命中则跳过预填，首包只剩解码与合成）；块 KV 追加（每块生成后把新 KV 写入连续槽位，槽位按块索引分配）；滚动释放（块播放完成后释放其 KV，仅保留注意力窗口所需的最近块）。</p>\n<p>公式上，块 $k$ 的显存占用为块 token 数乘以每 token KV 字节数乘以层数，总占用是活跃块数的线性函数而非总生成长度的线性函数——这正是滚动释放的意义。系统代价：前缀复用把 $t_{\\text{prefill}}$ 从首包预算里去掉，但缓存池本身占显存，命中率低时是纯浪费；滚动释放把显存从线性增长压成有界，但释放时机若晚于声码器消费，队列积压时显存仍会爬升。容量规划按“前缀池容量 + 最大并发活跃块数 × 块 KV”定显存上限，批大小由该上限反推。</p>\n<p>一个具体例子：多请求共享同一说话人提示时，前缀 KV 池命中使预填只做一次，后续请求直接进解码池；每个请求的音频块 KV 独立追加、独立释放，互不干扰。若某请求块过长，其单块 KV 占用超过槽位预算，调度器应拒绝或降块大小重排，而不是让显存越界。这层判断把“块大小”从性能参数升级为容量参数：块大小同时决定首包延迟、调度开销与单请求显存峰值，三者要在同一张预算表上配平。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-30\">三十 · 调度参数：SM 配额、队列深度与背压</h3>\n<p>调度参数是首包延迟抖动的直接来源。核心参数四个：预填 SM 配额比例、解码 SM 配额比例、声码器 SM 配额比例、各级队列深度。配额隔离是硬约束——预填与解码未做 SM 配额隔离时，预填长文本占满 SM，首包延迟秒级抖动。配额应按负载配方定：文本长度分布决定预填所需 SM 的下限，块大小与并发数决定解码所需 SM 的下限，声码器实时率决定其下限，三者之和不得超过卡上 SM 总数，超出则必须拆卡或降并发。</p>\n<p>队列深度与背压是软约束。解码池队列满时对新请求背压，避免预填完成的 KV 前缀堆积占显存；声码器队列满时对解码池背压，避免已生成块无人消费、KV 无法释放。伪代码思路：调度循环每步检查三级队列水位，水位超阈值则暂停上游准入；预填完成事件触发 KV 句柄移交并把预填槽位显存归还池；块完成事件触发声码器投递与 KV 槽位标记待释放。系统代价：配额切分越细，SM 利用率越低、吞吐下降；队列越深，抗抖动能力越强但显存与延迟尾部越差。工程判断是配额按 SLO 下限给、队列按 P99 首包预算给，不追求满利用率。</p>\n<p>一个具体例子：预填池配额不足时，长文本请求在预填队列排队，其首包延迟由排队时间主导而非计算时间；此时提高预填配额会挤压解码池，短请求首包反而变差。可复现的配置思路是：先按负载配方的文本长度分布与并发数算出三段 SM 下限，取整到卡上 SM 的可行切分，再把队列深度设为“单级处理速率的若干倍块时间”，最后用首包延迟 P99 与块间连续性两个 SLO 指标回归调参——先调块大小，再调配额，最后调队列深度，因为块大小同时影响三者，是杠杆最大的参数。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-31\">三十一 · 可复现配置思路：一张预算表串起五个旋钮</h3>\n<p>把硬件档位、并行拓扑、量化方案、KV 策略、调度参数收束成一张可复现的配置表，做法是按“预算—旋钮—验证指标”三列展开。预算行：首包延迟预算、块间连续性预算、显存上限、吞吐目标。旋钮行：卡数与档位（单卡/双卡/分离）、TP/DP 划分与声码器独立级、权重与 KV 精度、块大小与滚动释放窗口、三级 SM 配额与队列深度。验证行：首包延迟 P99、块切换处韵律指标、显存峰值曲线、解码出块速率与声码器实时率之比。配置的复现性来自顺序：先定预算，再按预算反推块大小（首包剩余额度除以单 token 解码步时间），再由块大小与并发定 KV 显存与批大小，再由三段负载定 SM 配额，最后选档位与拓扑。</p>\n<p>机制上，这张表把前文公式变成可执行约束：$$L_{\\text{first}} = t_{\\text{prefill}} + t_{\\text{ar}}(B) + t_{\\text{voc}}(B)$$ 中 $t_{\\text{prefill}}$ 由预填配额与 TP 度决定，$t_{\\text{ar}}(B)$ 由块大小 $B$ 与解码配额决定，$t_{\\text{voc}}(B)$ 由声码器配额与实时率决定；$$\\text{KV}_{\\text{audio}} \\propto B$$ 则把批大小与块大小绑在显存上限上。系统代价：预算表越紧，旋钮可行域越小，最终配置往往在“首包延迟达标但吞吐不满”或“吞吐满但首包 P99 越界”之间取折中；折中点由 SLO 决定，不由峰值算力决定。一个具体例子：若首包预算紧、文本长，则块大小取下限、预填配额上调、前缀 KV 池必开；若吞吐优先，则块大小上调、解码 DP 复制、声码器配额按实时率配平，接受首包略升。</p>\n<p>最后落在工程判断上：这套配置的稳定性不来自任何单点最优，而来自“预填完成即释放显存、块 KV 连续追加、首块 token 立即投递声码器”三条不变式在五个旋钮下的同时成立。任何一次调参若破坏其中一条——例如为省显存提前释放未消费块的 KV，或为降延迟把块切到破坏位置编码连续性——都会以首包抖动或韵律断裂的形式暴露。因此可复现的配置思路本质是：把三条不变式写成调度器断言，让五个旋钮在断言约束内搜索，而不是在指标上单独追优。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-32\">三十二 · 首包延迟的三项分解与 SM 争抢的量化</h3>\n<p>把首包延迟拆成三项，是判断规模上去以后哪里先崩的起点：</p>\n<div class=\"formula\">$$L_{\\text{first}} = t_{\\text{prefill}} + t_{\\text{ar}}(B) + t_{\\text{voc}}(B),\\quad \\text{KV}_{\\text{audio}} \\propto B$$</div>\n<p>三项里只有 $t_{\\text{ar}}(B)$ 与 $t_{\\text{voc}}(B)$ 随批大小 $B$ 增长，$t_{\\text{prefill}}$ 在文本长度固定时基本与 $B$ 无关，但它对 SM 的占用是突发性的：文本 LM 预填是一次大矩阵乘，会瞬间吃满可用 SM。若预填与音频解码共享同一组 SM 而无配额隔离，预填一开始，解码流就被挤出执行队列，首包延迟出现秒级抖动，流式播放直接卡顿。这是本形态最先崩的地方——不是显存，不是带宽，而是**SM 的时间片分配**。工程上的判断标准很直接：预填与解码是否跑在不同 CUDA stream 且带显式 SM 配额（如 green context 或 MPS 的 SM 百分比切分）。没有配额，批大小一上去，抖动幅度随预填文本长度线性放大。</p>\n<p>具体例子：一个零样本 TTS 请求带 200 字文本与 3 秒说话人提示，预填阶段占用接近全部 SM 数十毫秒量级；若此时解码流正在生成首块 token，解码被阻塞，首包波形从毫秒级退化到秒级。把预填挪到独立引擎、完成后立即释放其显存给解码 KV，是消除这项抖动的唯一结构性手段。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-33\">三十三 · KV 显存的线性膨胀与块滚动释放</h3>\n<p>音频侧 KV 按块追加，显存与已生成音频长度线性相关。公式上 $\\text{KV}_{\\text{audio}} \\propto B$ 只是批维度的表述，真正致命的是序列维度：长文本合成时，已生成音频 token 数持续增长，KV 不释放就线性膨胀直至 OOM。注意这里的 KV 有两段——文本预填 KV 与音频 KV 拼接为 $K_{\\text{text}}\\oplus K_{a,&lt;t}$，文本段是固定成本，音频段是增长成本。批大小受两者之和约束，而非单看音频段。</p>\n<p>代价核算的思路：每块 token 数记为 $C$，块数记为 $N$，则音频 KV 元素数正比于 $N\\cdot C$，与批大小相乘后即为显存占用。块过短（$C$ 小）会让 $N$ 变大，调度开销与块切换次数上升；块过长则首包延迟回升，因为首块要等更长的自回归序列才送声码器。这是一个双向夹逼的调参面，不是单调优化。</p>\n<p>工程上必须做**块滚动释放**：已完成块的 KV 在声码器消费完毕后即回收，只保留声码器重叠窗口所需的最短历史。若不回收，长文本合成的显存曲线是单调上升的直线，OOM 只是时间问题。具体例子：一段数分钟的有声书合成，若每块都保留全部历史 KV，显存随播放进度线性爬升；改为滚动释放后，显存稳定在一个与块长和重叠窗口相关的平台上，批大小才能放开。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-34\">三十四 · 带宽：声码器流水线与 KV 读写的双重压力</h3>\n<p>解码阶段每生成一个 token 都要读全部历史 KV，这是典型的带宽受限而非算力受限。Blackwell 上单卡 HBM 带宽很高，但音频 LM 的隐藏维通常不大，矩阵乘的算术强度低，实际瓶颈落在 KV 读取上。批大小增大能摊薄权重读取，却摊薄不了 KV 读取——每个请求的 KV 是私有的。因此吞吐随批大小的增长曲线会提前饱和。</p>\n<p>更隐蔽的一层是声码器与 LM 解码的流水并行带来的带宽叠加：声码器做上采样与卷积，是访存密集型算子，与 LM 解码的 KV 读取争抢同一份 HBM 带宽。两者若在同一 GPU 上流水，带宽需求是相加而非重叠。分离到不同引擎（甚至不同 GPU）能把这条曲线拆开，代价是块 token 需要跨设备传输，引入通信延迟。</p>\n<p>具体例子：首块 token 立即送入流式声码器时，声码器正在处理第 $k$ 块波形，LM 同时在生成第 $k+1$ 块 token。若两者同卡，声码器的卷积访存会把 LM 解码的 KV 读取拖慢，块间节奏出现周期性抖动；把声码器放到独立流并限制其 SM 占用，抖动收敛。这就是为什么部署配方里强调“声码器与 LM 解码流水并行”必须配合资源隔离，而不是简单并发。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-35\">三十五 · 通信：预填-解码分离后的跨设备代价</h3>\n<p>当文本预填与音频解码被拆到不同流/引擎，甚至不同 GPU，条件 KV 必须从预填侧传到解码侧。$K_{\\text{text}},V_{\\text{text}}$ 的体量由文本长度与层数决定，属于一次性传输，但它在首包关键路径上：传输不完成，音频侧无法开始自回归。NVLink 5 的带宽让这项传输在节点内可接受，跨节点则要经过 NIC，首包延迟直接加上一个网络往返。</p>\n<p>规模上去以后，通信先崩的位置在**批内多请求的条件 KV 聚合**：每个请求的文本长度不同，KV 传输量不均，短请求等长请求，形成队头阻塞。调度器若按请求到达顺序而非按 KV 就绪顺序派发解码，长文本请求会拖住整批的首包。解法是把预填完成事件作为解码调度的触发条件，KV 一到即入解码队列，而不是等整批预填齐。</p>\n<p>另一个通信面是块 token 从 LM 到声码器的传递。块越长，单次传输越大、次数越少，通信开销占比下降，但首包延迟上升；块越短则相反。这与第二节的块长夹逼是同一个参数在两个维度上的拉扯，工程上按 SLO 的首包上限反推块长上界，再按带宽利用率定下界。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-36\">三十六 · 功耗与尾延迟：批大小的收益边界</h3>\n<p>功耗在推理侧不是均匀的：预填是短时高功率尖峰，解码是长时中功率平台，声码器是持续访存型功耗。三者叠加时，GPU 的功率封顶会触发降频，而降频对预填的影响最大——预填本就是算力密集，降频直接拉长 $t_{\\text{prefill}}$，首包延迟抖动加剧。这就是为什么在高负载下，即便 SM 配额做对了，首包延迟仍会出现与功率封顶相关的周期性劣化。</p>\n<p>尾延迟的来源可以归为三类：SM 争抢（第一节）、KV 传输队头阻塞（第四节）、功率降频（本节）。三者中只有第一类能靠配额结构性消除，后两类只能靠调度策略缓解。P99 首包延迟随批大小上升的速度通常快于 P50，因为尾部的请求恰好撞上预填尖峰或功率封顶窗口。</p>\n<p>具体例子：一批零样本 TTS 请求同时到达，预填集中触发功率尖峰，解码侧正在生成的请求被降频拖慢，其块间间隔拉长，声码器流水线出现空泡。把预填按时间窗错峰派发（而非一次性全放），能把功率曲线压平，尾延迟收敛。这是调度器在预填与解码间分配 SM 之外的第二个职责：分配**时间**。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-37\">三十七 · 规模上去以后先崩的顺序</h3>\n<p>把五个维度按“先崩”排序，对本形态有明确的工程含义。第一崩的是 SM 争抢导致的首包抖动——它不需要规模很大就会出现，只要预填文本够长、解码正在关键路径上。第二崩的是 KV 显存线性膨胀——批大小与音频长度同时上升时，未滚动释放的 KV 直接把批大小锁死。第三崩的是带宽饱和——批大小继续放大后，KV 读取与声码器访存叠加，吞吐曲线走平。第四崩的是跨设备条件 KV 传输的队头阻塞——只有在预填与解码真正分离部署后才显现。功耗降频贯穿始终，是尾延迟的底色而非独立拐点。</p>\n<p>对应的容量规划判断：批大小不应按平均显存占用定，而应按“最长文本 + 最长音频块 + 重叠窗口”的峰值 KV 定；SM 配额应按预填尖峰的瞬时需求留出隔离带，而不是让预填与解码共享弹性池；块长按首包 SLO 反推上界、按通信与调度开销定下界。任何一项按平均值估算，都会在尾部请求上崩掉。</p>\n<p>最后落在一个具体机制上：调度器释放预填显存给解码 KV 的时机，必须绑定在“条件 KV 已写入解码侧”这一事件上，而非“预填 kernel 已启动”或“预填流已空闲”。绑定早了，解码侧读到不完整的 $K_{\\text{text}}\\oplus K_{a,&lt;t}$，块间韵律断裂；绑定晚了，显存空转，批大小上不去。这个事件的粒度，就是本形态规模上限的真正刻度。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-38\">三十八 · 预填-解码流水线的崩溃点：SM 争抢、块边界与 KV 线性膨胀</h3>\n<p>把文本预填与音频解码拆到不同流之后，系统代价并没有消失，只是从“串行等待”转移成了“资源竞争 + 状态连续性 + 显存增长”三条互相耦合的约束。首包延迟可以写成三段之和：<div class=\"formula\">$$L_{\\text{first}} = t_{\\text{prefill}} + t_{\\text{ar}}(B) + t_{\\text{voc}}(B),\\quad \\text{KV}_{\\text{audio}} \\propto B$$</div>其中 $B$ 是首块音频 token 数。这个式子暴露了一个直接的工程判断：块长 $B$ 是唯一同时出现在延迟与显存两项里的旋钮——$B$ 增大，$t_{\\text{ar}}(B)$ 与声码器解码时间线性上升，首包变慢；$B$ 减小，块数变多，调度与流水切换开销上升，SM 配额切换的粒度变细，抖动反而更难压住。块过短增加调度开销、块过长使首包延迟回升，这两条边界不是调参偏好，而是 $L_{\\text{first}}$ 对 $B$ 的非单调性决定的。</p>\n<p>规模上去以后第一个崩的通常不是显存容量，而是 SM 配额隔离失效下的尾延迟。文本预填是计算密集型、对 SM 占用是突发式的整块索取；音频解码是访存密集型、需要稳定的小额 SM 配额维持块间节奏。两者共享同一 GPU 时，若调度器不做显式配额划分，一段长文本的预填会把 SM 占满，解码流被饿死，首包延迟出现秒级抖动、流式播放卡顿——这是本方案最典型的失败模式，且它只在负载变重、文本变长时才显形，单请求压测看不出来。工程上的对策是把预填与解码放进不同流甚至不同引擎，并给解码侧保留不可被预填抢占的最小 SM 份额；预填完成即释放其显存给解码 KV，让显存与 SM 两笔账在同一时刻完成交接，而不是各自独立回收。</p>\n<p>第二个崩点是块边界的 KV 连续性。带前缀 KV 的解码形式为<div class=\"formula\">$$p(a_t\\mid a_{&lt;t},c)=\\mathrm{softmax}(W h_t),\\quad h_t=\\mathrm{Attn}(q_t,K_{\\text{text}}\\oplus K_{a,&lt;t},V_{\\text{text}}\\oplus V_{a,&lt;t})$$</div>音频侧每一块都必须以 $K_{\\text{text}}\\oplus K_{a,&lt;t}$ 的完整前缀做注意力，块间不能重置位置编码、不能重建 KV，否则 $h_t$ 的条件分布发生跳变，合成语音在块切换处出现韵律断裂或音色跳变。这条约束把“按块流式”从无状态的切片变成了有状态的追加：块是计费与调度粒度，但 KV 必须是单调增长的单一序列。代价是解码侧无法像无状态服务那样自由迁移请求，块边界成了必须保序的同步点。</p>\n<p>第三个崩点是 KV 的线性膨胀与释放时机。$\\text{KV}_{\\text{audio}} \\propto B$ 意味着长文本合成的显存随已生成音频长度单调上升；若只追加不释放，已完成块的 KV 仍占着显存，长文本合成时显存线性膨胀直至 OOM。可行的做法是按块滚动释放——保留注意力仍需要的窗口，丢弃已滑出感受野的历史 KV，把显存从“与总时长成正比”压回“与窗口加当前块成正比”。这与批大小直接冲突：批大小受 KV 显存与块数约束，显存回收越保守，可并发的请求数越少，吞吐上不去；回收越激进，块边界的一致性风险越高。规模化的实际瓶颈因此落在调度精度上——SM 配额、块长、KV 释放窗口三者要联合整定，任何一项单独调优都会在另一项上付出尾延迟或 OOM 的代价。</p>\n<table class=\"mini\"><thead><tr><th>规模上升时的先崩项</th><th>触发条件</th><th>系统代价</th></tr></thead><tbody><tr><td>尾延迟抖动</td><td>预填长文本占满 SM，解码流无配额</td><td>首包秒级抖动、播放卡顿</td></tr><tr><td>韵律不连续</td><td>块边界重置位置编码或重建 KV</td><td>块切换处音色跳变，需重生成</td></tr><tr><td>显存 OOM</td><td>KV 按块增长但不滚动释放</td><td>长文本合成显存线性膨胀</td></tr></tbody></table>\n<h3 id=\"alg-codec-lm-stream-sec-39\">三十九 · 精度失效：从条件 KV 污染到块边界漂移</h3>\n<p>流式编解码器 LM 的精度问题很少表现为整句崩坏，而是集中在两个位置：文本条件 KV 的数值退化，以及块边界处自回归状态的漂移。前者源于文本预填与音频解码被拆到不同流/引擎后，<code>K_text</code>、<code>V_text</code> 以 FP16 落在显存中，若文本侧使用了不同的量化路径（例如文本 LM 走 FP8 预填、音频 LM 以 FP16 读取前缀），前缀 KV 的尺度与音频侧注意力权重的尺度不匹配，softmax 的 logits 分布被系统性拉偏，表现为首块音色偏离说话人提示、或高频细节被抹平。诊断上不要只看波形，应在音频 LM 每层注意力输出上挂 per-head 的 logits 熵与 top-1/top-2 margin 统计：条件 KV 污染时，首块若干步的熵会异常低（模型过度自信地复读提示音素）或异常高（注意力失焦）。</p>\n<p>块边界漂移则是另一类：块切换时若位置编码被重置、或 KV 追加时未把上一块的末尾 token 一并带入注意力窗口，<code>h_t = Attn(q_t, K_text⊕K_{a,&lt;t}, V_text⊕V_{a,&lt;t})</code> 中的 <code>K_{a,&lt;t}</code> 在边界处出现断层，韵律在块接缝处断裂。工程上把「块边界前后各 N 步的注意力对上一块末尾 token 的权重和」作为连续性指标，低于阈值即判定 KV 不连续。代价是显性的：一次块边界断裂在听感上是可感知的卡顿，而修复它往往要回滚到上一块重解码，直接吃掉一个块的解码时间预算。</p>\n<div class=\"formula\">$$\\text{drift}_k=\\big\\|\\,h_t^{\\text{blk}=k}-h_t^{\\text{blk}=k-1}\\big\\|_2\\Big/\\|h_t^{\\text{blk}=k-1}\\|_2,\\quad \\text{告警当 drift}_k&gt;\\tau$$</div>\n<p>具体例子：说话人提示编码为条件 token 后，文本 LM 预填得到 KV；若文本侧预填用了低比特、音频侧按 FP16 读取，首块生成的第 1–8 个 token 的 top-1 margin 会明显低于后续块，此时应优先怀疑前缀 KV 的精度路径不一致，而不是声码器。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-40\">四十 · OOM：KV 按块增长与释放时机</h3>\n<p>本系统的显存模型是 <code>KV_audio ∝ B</code>，且随已生成音频长度线性增长。OOM 几乎不来自单次分配失败，而来自「已完成块的 KV 没有及时释放」与「批内长短请求混排」的叠加：一个长文本合成请求持续追加块，KV 线性膨胀，而同批的短请求早已解码完毕却仍占着批槽，调度器按批预留的显存水位被长请求顶穿。诊断的关键是把显存拆成三本账——文本预填 KV（预填完成即应释放给解码 KV）、音频 KV（按块追加）、声码器流水缓冲——并在每块追加前后采样 <code>torch.cuda.memory_allocated</code> 与 reserved 的差值。若 allocated 随块数单调上升而 reserved 阶梯跳变，说明碎片化而非真实需求增长。</p>\n<p>回滚策略要按粒度设计：块级回滚（丢弃最近一块的 KV 并重解码）成本最低，但会引入一次可感知的接缝；请求级回滚（整条请求降级到更小批或更短块长重跑）成本高但语义干净。工程判断是——当 OOM 发生在长文本的第 k 块，优先做块级回滚并把该请求迁到独立流，避免污染同批其他请求的 SLO。代价上，块级回滚重解码一个块的延迟约等于一次块解码时间，而请求级回滚要重付文本预填的 <code>t_prefill</code>，在长文本上后者是前者的数倍。</p>\n<table class=\"mini\"><thead><tr><th>现象</th><th>判据</th><th>首选动作</th></tr></thead><tbody><tr><td>allocated 随块线性升</td><td>已完成块 KV 未释放</td><td>块级释放 + 块级回滚</td></tr><tr><td>reserved 阶梯跳变</td><td>碎片化</td><td>换分配器/预分配池，不重跑</td></tr><tr><td>批槽被长请求占满</td><td>长短混排</td><td>请求级迁移到独立流</td></tr></tbody></table>\n\n<h3 id=\"alg-codec-lm-stream-sec-41\">四十一 · 批抖动与路由不均：SM 配额是根因</h3>\n<p>首包延迟抖动的主因是文本预填与音频解码争抢 SM 而未做配额隔离：预填长文本会占满 SM，解码侧拿不到 SM 就无法按时产出首块 token，<code>L_first = t_prefill + t_ar(B) + t_voc(B)</code> 中的 <code>t_ar(B)</code> 被拉长，流式播放出现卡顿。诊断不能只看端到端 P99，要把 <code>L_first</code> 拆成三段分别打点：预填占用 SM 的时长、首块自回归的排队等待、声码器首帧的排队等待。若预填时长与首包延迟强相关而解码等待也同步上升，即为 SM 争抢；若预填正常而解码等待高，则是批内调度顺序问题（解码请求被排到预填之后）。</p>\n<p>路由不均出现在多引擎/多流部署下：请求按哈希或轮询落到文本预填引擎与音频解码引擎，若两端的块长与批大小策略不一致，某些解码引擎会持续拿到长块请求，形成热点。判据是各引擎的「块解码时长 / 块 token 数」分布偏移，热点引擎的该比值显著高于均值。回滚动作是把路由从静态哈希切到基于队列水位的加权路由，并把块长上限在热点引擎上临时下调。代价是路由切换本身会带来一次在途请求的重新排队，尾延迟会有一个短尖刺，因此切换要放在低峰或按引擎逐个灰度。</p>\n<div class=\"formula\">$$\\text{热点判据}:\\ \\frac{\\overline{t_{\\text{blk}}/n_{\\text{tok}}}^{\\,\\text{engine }i}}{\\overline{t_{\\text{blk}}/n_{\\text{tok}}}^{\\,\\text{all}}}&gt;\\rho$$</div>\n<p>具体例子：零样本 TTS 请求的文本长度方差大，短提示请求与长文本请求同批时，长文本预填把 SM 占满，短请求的首块 token 被推迟，表现为「短请求反而首包更慢」的反直觉现象——这正是配额未隔离的典型指纹。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-42\">四十二 · 尾延迟尖刺：块过长与声码器流水阻塞</h3>\n<p>尾延迟尖刺有两个独立来源。其一是块过长：块越长，首块 token 的自回归步数越多，<code>t_ar(B)</code> 越大，首包延迟回升；块过短则调度开销上升，块切换频繁，接缝风险增加。这是一个双向约束，尖刺往往出现在块长被动态调整的时刻——例如为降 OOM 临时调小块长，导致块切换次数骤增，声码器流水线在接缝处反复启停。其二是声码器与 LM 解码的流水并行失配：声码器按块消费 token，若 LM 解码快于声码器，token 缓冲积压；若声码器快于 LM，声码器空转等待，两者都会在块边界形成尖刺。诊断上分别统计「块解码完成到声码器首帧输出」的等待时长与「声码器消费速率 / LM 产出速率」的比值，前者尖刺指向调度，后者偏离 1 指向流水失配。</p>\n<p>回滚上，块长应作为受控变量而非应急手段：把块长变更纳入灰度，变更后观察至少一个完整请求周期的接缝指标与首包 P99，再决定是否保留。声码器侧的回滚是临时增大 token 缓冲深度以吸收尖刺，但这会抬高显存水位，必须与 OOM 监控联动。代价明确：缓冲深度每增加一块，显存多占一份块级 KV 等价的缓冲，长文本下这是线性叠加的。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-43\">四十三 · 监控面与回滚闸门</h3>\n<p>监控要覆盖四个面，且每个面都要有可执行的闸门而非仅告警。第一面是首包三段分解（预填 SM 时长、首块 AR 等待、声码器首帧等待），闸门是任一段超过其基线的倍数即触发 SM 配额重分配。第二面是块接缝连续性（边界注意力权重和、drift_k），闸门是连续两块 drift 超阈值即冻结当前块长并回滚到上一块。第三面是显存三本账（预填 KV、音频 KV、声码器缓冲），闸门是音频 KV 增速超过块数线性预期即触发块级释放与请求迁移。第四面是路由分布（各引擎块解码时长/token 数），闸门是热点比值超 ρ 即切加权路由。四面的采样粒度必须到块级，因为本系统的计费与 SLO 都以块为粒度，批级采样会把尖刺平均掉。</p>\n<p>回滚闸门的设计原则是「先降级、后重跑」：能通过配额调整、块长冻结、缓冲加深、路由加权解决的，不触发请求级重跑；只有当精度指标（logits 熵、drift）与显存指标同时越界，才判定为不可就地修复，执行请求级回滚并保留现场（前缀 KV 快照、块边界 token 序列）供离线复现。工程判断落在这一点上——流式编解码器 LM 的失败大多是可局部修复的状态问题，而非模型问题，因此回滚的默认粒度应是块，而不是请求；把请求级重跑当作最后手段，才能把 <code>t_prefill</code> 的重复付出压到最低。</p>\n<p>具体例子：长文本合成在第 k 块触发 OOM 闸门，先做块级释放并把该请求迁到独立流，若 drift_k 同时越界则回滚到第 k−1 块重解码；只有当迁移后仍在同一块 OOM，才升级为请求级回滚并保留前缀 KV 快照。这条路径把大多数 OOM 挡在块级，避免了对整段文本预填的重复计费。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-44\">四十四 · 流式预填解码的失效边界与回滚判据</h3>\n<p>这套方案最脆弱的时刻不在稳态解码，而在文本预填尚未释放显存、音频首块已经开始争抢 SM 的那一小段重叠窗口。若预填与解码不做 SM 配额隔离，长文本预填会占满可用 SM，音频侧首块 token 的自回归被推迟到预填尾部才获得执行机会，首包波形延迟出现秒级抖动，流式播放表现为开头静默后突然起播。诊断上应把 <span class=\"formula\">$$L_{\\text{first}} = t_{\\text{prefill}} + t_{\\text{ar}}(B) + t_{\\text{voc}}(B)$$</span> 拆成三段独立打点：预填排队时长、首块自回归时长、声码器首帧时长，任一段的 P99 相对 P50 的偏离超过阈值即判定为争抢而非模型变慢。监控指标至少包括每请求的 SM 占用快照、预填完成到首块 token 落地的间隔、以及块间 token 间隔的方差；后者是韵律连续性的代理信号，方差突增往往先于听感异常出现。</p>\n<p>显存侧的失效是渐进的：KV cache 按块增长，$\\text{KV}_{\\text{audio}} \\propto B$ 意味着显存与已生成音频长度线性相关，一旦已完成块的 KV 未随块切换滚动释放，长文本合成会在中途把显存推至 OOM，而 OOM 发生时往往正是批内某条长请求拖住整批的时刻。工程上应把“块完成即释放”做成硬约束而非优化项，并在调度器里保留一条按块计费的显存水位线；当水位线触顶时优先驱逐最长已生成块而非整请求，避免整批回滚。批抖动与路由不均同源：块数决定计费粒度，块过短使调度开销压过解码收益，块过长则首包延迟回升，二者在批内混合长短请求时表现为尾延迟尖刺——少数长文本请求占住预填 SM，短请求的首包被系统性拖慢。</p>\n<p>精度与连续性问题的诊断不能只看 loss 或波形相似度。块间 KV 追加若在块边界重置位置编码或截断注意力窗口，$K_{\\text{text}}\\oplus K_{a,&lt;t}$ 的前缀连续性被破坏，合成语音在块切换处出现韵律断裂或音色跳变，这类失效在逐块拼接的离线评估里几乎不可见，只有流式播放的边界帧能量突变和基频轨迹断点能稳定捕获。回滚策略应分层：SM 配额调度参数可热切换，先回退到预填独占、解码让路的保守配额以消除首包抖动；KV 连续性异常则回退到块边界不重置位置编码的追加路径；显存膨胀导致的 OOM 回滚到按块滚动释放的旧版本调度器，并以块长为单位重放最近若干请求验证水位线。所有回滚都应以块为最小单位记录，因为块既是计费粒度也是显存与连续性的共同边界，按请求回滚会掩盖真正的失效点。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>可观测信号</th><th>回滚动作</th></tr></thead><tbody><tr><td>预填/解码争抢 SM</td><td>首包延迟 P99 偏离、预填排队时长尖刺</td><td>回退保守 SM 配额，预填独占优先</td></tr><tr><td>块边界 KV 不连续</td><td>边界帧能量突变、基频轨迹断点</td><td>回退不重置位置编码的追加路径</td></tr><tr><td>块 KV 未释放致 OOM</td><td>显存水位随块数线性抬升</td><td>回退按块滚动释放的调度器版本</td></tr></tbody></table>\n<h3 id=\"alg-codec-lm-stream-sec-45\">四十五 · 对照轴：把候选算法放在同一张坐标上</h3>\n<p>本片段要解决的不是“流式编解码器 LM 怎么做”，而是“在它和它的邻居之间怎么选”。为此需要先把候选算法投影到同一组可比较的轴上，而不是凭直觉。对零样本 TTS 的推理链路，真正决定选型的轴只有四条：首包延迟的来源、条件信息的注入方式、KV 显存随输出长度的增长形态、以及 SM 资源在时间上的占用形状。本片段的主角——文本预填与音频解码分离的流式编解码器 LM——在这四条轴上的坐标是：首包延迟由“首块 token 数 × 单步解码”决定而非整段文本长度；条件以文本预填 KV 前缀注入；KV 显存随已生成音频长度线性增长；SM 占用呈“短促预填 + 长尾解码”的两段式。</p>\n<p>把同族算法放到这四条轴上，差异立刻显形。整段预填后一次性自回归生成的传统编解码器 LM，首包延迟被整段文本预填与全部音频 token 生成共同支配，KV 显存在首包时刻就达到峰值；级联 ASR/LLM/TTS 的首包延迟是三段串行往返之和，但每段都可独立扩缩容；双流全双工语音对话推理不区分预填与解码阶段，SM 占用近似恒定但首包语义不同；非自回归时长预测批推理把延迟压到单次前向，代价是放弃逐 token 的条件依赖。选型的第一条判据因此不是“谁更快”，而是“首包延迟的瓶颈落在哪一段”。若瓶颈是文本预填，分离式方案直接命中；若瓶颈是声码器，则应去查声码器分块批合成那条线，而不是在这里加码。</p>\n<div class=\"formula\">$$L_{\\text{first}} = t_{\\text{prefill}} + t_{\\text{ar}}(B) + t_{\\text{voc}}(B),\\quad \\text{KV}_{\\text{audio}} \\propto B$$</div>\n<p>这个式子给出选型的定量骨架：$B$ 是首块 token 数，$t_{\\text{ar}}(B)$ 与 $t_{\\text{voc}}(B)$ 都随 $B$ 单调增，而 $\\text{KV}_{\\text{audio}}$ 与已生成音频长度成正比。分离式方案的全部收益来自把 $t_{\\text{prefill}}$ 从关键路径上摘出去、并把 $B$ 压到很小；全部代价则来自 $B$ 太小导致块间切换频繁、以及预填与解码争抢 SM 带来的抖动。任何对照都必须在这三项上做取舍，而不能只比较总吞吐。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-46\">四十六 · 决策表：五类候选与它们的适用条件</h3>\n<p>下表把与本算法直接竞争的几类推理形态并列，给出“选它的条件”与“不选它的信号”。表中不写绝对数字，只写相对关系与触发条件，因为容量结论依赖具体 GPU 档位与模型规模。</p>\n<table class=\"mini\"><thead><tr><th>候选形态</th><th>首包延迟瓶颈</th><th>KV/显存形态</th><th>选它的条件</th><th>应改选他处的信号</th></tr></thead><tbody>\n<tr><td>整段预填 + 一次性自回归（传统编解码器 LM）</td><td>整段文本预填 + 全部音频 token</td><td>首包即峰值，随总时长线性</td><td>离线批量合成、对首包无 SLO</td><td>存在首包 SLO，且文本较长</td></tr>\n<tr><td>文本预填/音频解码分离的流式编解码器 LM（本算法）</td><td>首块 token 数 × 单步解码</td><td>随已生成音频长度线性、按块追加</td><td>零样本 TTS、首包敏感、文本中等长度</td><td>文本极长且块滚动释放未做；SM 配额无法隔离</td></tr>\n<tr><td>级联 ASR/LLM/TTS</td><td>三段串行往返之和</td><td>各段独立，无共享 KV</td><td>需要文本中间表征可审计、各段可独立扩缩容</td><td>端到端延迟预算紧、往返开销占比高</td></tr>\n<tr><td>双流全双工对话推理</td><td>由对话轮次语义决定，非首包 token</td><td>双向流共享，持续占用</td><td>实时交互、需打断与插话</td><td>仅需单向朗读式合成</td></tr>\n<tr><td>非自回归时长预测批推理</td><td>单次前向</td><td>与输出长度弱相关</td><td>时长可控、韵律要求宽松、吞吐优先</td><td>零样本音色克隆、需逐 token 条件依赖</td></tr>\n</tbody></table>\n<p>读表的方式是自上而下排除：先看有没有首包 SLO，没有则整段预填方案最省工程复杂度；有则看条件信息是否必须逐 token 参与，若必须，非自回归出局；再看是否需要双向交互，若需要则本算法让位于全双工形态；最后看文本长度与 SM 隔离能力，这两条决定本算法能否兑现它的延迟承诺。级联方案常被误当作“更简单所以更稳”，但它的三段往返在端到端预算紧时会把首包延迟推高，且段间接口的序列化开销不体现在任何单段指标里。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-47\">四十七 · 同族内部的二次选择：块长与预填/解码的耦合度</h3>\n<p>即便确定了用分离式流式编解码器 LM，同族内部仍有两个连续可调的自由度，它们决定了这套算法在自身适用区间内的位置。第一个是块长 $B$：$B$ 增大则 $t_{\\text{ar}}(B)$ 与 $t_{\\text{voc}}(B)$ 上升、首包延迟回升，但块间切换次数下降、韵律断裂风险下降、调度开销下降；$B$ 减小则相反。存在一个由 SLO 反解出的上界：给定首包预算 $L_{\\text{first}}^{\\max}$，需满足 $t_{\\text{prefill}} + t_{\\text{ar}}(B) + t_{\\text{voc}}(B) \\le L_{\\text{first}}^{\\max}$，块长不能超过使该式取等号的 $B$。这条约束是硬约束，不是调优点。</p>\n<p>第二个自由度是预填与解码的耦合度，从“同引擎同流、仅靠调度器分时”到“异引擎、显式 KV 交接”构成一条谱。耦合越松，预填长文本占满 SM 的风险越低，但 KV 交接的拷贝与同步成本越高；耦合越紧，交接成本低，但对 SM 配额调度的精度要求陡增。工程判断是：当文本长度分布的长尾显著（少数请求文本极长）时，必须走向松耦合，否则长文本请求会把同批短请求的首包延迟一起拖垮；当文本长度集中且短时，紧耦合的调度开销更低。</p>\n<ul>\n<li>机制上，松耦合需要在预填完成时把 $K_{\\text{text}},V_{\\text{text}}$ 显式移交解码侧，移交的字节量正比于文本 token 数 × 层数 × 头维度，这是一次不可忽略的带宽事件。</li>\n<li>紧耦合则依赖调度器在预填与解码间切分 SM，切分粒度过粗会让解码侧在预填期间停摆，过细则调度本身成为开销。</li>\n<li>无论哪种耦合，块间 KV 必须保持位置编码连续，块边界重置位置编码会在波形上表现为韵律断裂或音色跳变，这是本算法最典型的失败模式，诊断时应优先排查块边界的 KV 拼接而非模型权重。</li>\n</ul>\n\n<h3 id=\"alg-codec-lm-stream-sec-48\">四十八 · 代价对照：延迟、吞吐、显存、带宽各让一步</h3>\n<p>选型的本质是四类代价的再分配，没有一种形态能同时占优。分离式流式方案把延迟代价从“文本长度”转移到“块切换频率”，把显存代价从“峰值预留”转移到“按块增长的滚动释放”，把带宽代价新增在“预填 KV 移交”上，把吞吐代价落在“预填与解码无法满负荷并行”上。整段预填方案则相反：延迟与显存都在首包时刻集中支付，但吞吐可以靠大批量摊薄，带宽上没有移交事件。级联方案把延迟拆成三段可分别优化的和，但每段都有自己的批调度与显存峰值，总显存是三段之和而非共享。</p>\n<p>一个具体的工程例子：同一台服务端 GPU 上，若把文本预填与音频解码放在同一引擎且不做 SM 配额隔离，长文本请求的预填会占满 SM，解码侧停摆，首包延迟出现秒级抖动、流式播放卡顿——这正是失败模式清单里的第一条。改为异引擎并显式移交 KV 后，抖动消失，但每次请求多出一次 KV 拷贝，在文本 token 数较大时该拷贝的带宽占用可与一次解码步相当。若进一步把已完成块的 KV 及时释放，长文本合成的显存线性膨胀被截断，避免 OOM；若不释放，显存随已生成音频长度单调上升直至触顶。这三步改动没有改变模型，只改变了资源在时间上的分布。</p>\n<div class=\"formula\">$$\\text{吞吐}_{\\text{有效}} \\approx \\frac{N_{\\text{req}} \\cdot \\bar{T}_{\\text{audio}}}{T_{\\text{wall}}},\\quad T_{\\text{wall}} \\ge \\max\\!\\left(\\sum t_{\\text{prefill}},\\,\\sum t_{\\text{ar}},\\,\\sum t_{\\text{voc}}\\right)$$</div>\n<p>该式说明：分离式方案的墙钟时间下界由三段中最长的一段决定，而非三段之和，这是它相对级联串行的吞吐优势来源；但三段无法同时满负荷，因为预填与解码共享同一批 SM，实际有效吞吐介于“最长段”与“三段之和”之间，具体位置由 SM 配额调度精度决定。这也是为什么本算法的容量规划必须把调度精度当作一等参数，而不能只按 FLOPs 折算。</p>\n\n<h3 id=\"alg-codec-lm-stream-sec-49\">四十九 · 适用条件的边界判定与切换信号</h3>\n<p>给出可操作的切换判据，比给出“适用/不适用”的二元结论更有用。以下四条信号中任意一条持续出现，就应重新评估是否仍应使用分离式流式编解码器 LM，而不是继续调参：其一，首包延迟的方差显著大于其均值，说明预填与解码的 SM 争抢未被隔离，此时应改耦合度而非改块长；其二，块切换处的听感缺陷成为主要投诉，说明块长过短或位置编码未连续，应增大块长并检查 KV 拼接；其三，显存随请求时长单调上升且无平台期，说明已完成块的 KV 未释放，应引入滚动释放；其四，端到端预算中预填占比持续下降而声码器占比上升，说明瓶颈已迁移到声码器，应转向声码器分块批合成那条线，而不是在本算法上继续加压。</p>\n<p>反向的切换信号同样明确：当请求全部为离线批量、无首包 SLO 时，整段预填方案在工程复杂度与吞吐上都更优，引入分离式只会增加移交带宽与调度代码；当交互需要打断与插话时，单向的预填-解码流水线无法表达双向语义，应改用双流全双工形态；当韵律要求宽松且时长可控时，非自回归批推理的单次前向延迟远低于逐 token 解码，逐 token 条件依赖的收益不足以补偿延迟。这些判断的共同点是：先确定 SLO 的形状（首包、稳态、尾延迟各占多少权重），再选形态，而不是先选形态再解释 SLO。</p>\n<ul>\n<li>规模上限方面，本算法受 KV 显存与 SM 调度精度双重约束：块过短增加调度开销，块过长使首包延迟上升，两者夹出一个可行块长区间。</li>\n<li>长文本场景必须按块滚动释放 KV，否则显存线性增长会先于算力成为瓶颈。</li>\n<li>量化档位以 FP16 为主时，KV 移交的带宽成本随文本长度线性上升，这是松耦合方案在大文本下的隐性代价。</li>\n</ul>\n<p>最终的工程判断落在一个具体机制上：把“预填完成即释放其显存给解码 KV”作为调度器的硬规则，而不是优化项。这条规则同时约束了显存峰值与 SM 占用形状，使首包延迟的方差可控；一旦这条规则被绕过，前面所有关于块长与耦合度的调优都会失效，因为争抢重新回到了关键路径上。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2024 · 语音识别与音频理解推理</td></tr><tr><td>解决什么</td><td>零样本 TTS 的编解码器语言模型需先编码整段文本再自回归生成，首包延迟高，且文本预填与音频解码争抢 GPU 资源。</td></tr><tr><td>一句话机制</td><td>将文本预填与音频 token 解码分离到不同流/引擎，文本侧一次预填 KV 后，音频侧按块自回归解码并流式送声码器，实…</td></tr><tr><td>代价与失效</td><td>预填与解码争抢 SM 时需精细调度，否则首包延迟抖动；块间声学一致性依赖 KV 连续性，块切换可能引入韵律不连续</td></tr><tr><td>后继</td><td>编解码语言模型投机解码</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-codec-lm-stream · 共 8 个片段</p>\n";break;}}})();
